  async expMD(){await this.save(this.fname('md').replace(/-(diagram|sequence)\.md$/,'-mermaid.md'),this.mermaid());},
  async expJSON(){await this.save(this.fname('json').replace(/-(diagram|sequence)\.json$/,'.json'),JSON.stringify(JSON.parse(this.defJSON()),null,2));},
