  const hist=new Map();frames.forEach(f=>{const d=get(f);for(let i=0;i<d.length;i+=16){const k=((d[i]>>4)<<8)|((d[i+1]>>4)<<4)|(d[i+2]>>4);let h=hist.get(k);if(!h){h=[0,0,0,0];hist.set(k,h);}h[0]++;h[1]+=d[i];h[2]+=d[i+1];h[3]+=d[i+2];}});
