/* ---------- MCP SEQUENCE ---------- */
DEFS.mcpseq=(()=>{const L=[['app','AI Application','agent / LLM','green','Needs context and capabilities. Decides what to call and uses the result.'],['cli','MCP Client','discover · select · request','blue','Lives in the host and handles one connection per server.'],['srv','MCP Server','tools · data · resources','blue','Exposes capabilities via MCP and translates calls to the real system.'],['ext','External system','DB · API · files · SaaS','gray','The real system.']];
 const LX=[130,380,630,870],nodes=[],edges=[];
 L.forEach(([id,t,s,c,d],i)=>{nodes.push(N(id,LX[i]-85,10,170,54,t,s,c,d));nodes.push(Object.assign(N(id+'_e',LX[i],530,0,0,'','','gray',''),{pt:1}));edges.push(E(id,id+'_e',{noarrow:1,cls:'life'}));});
 const lx={app:LX[0],cli:LX[1],srv:LX[2],ext:LX[3]};
 const M=[['cli','srv',110,'tools/list · resources/list'],['srv','cli',140,'capabilities list',1],['app','cli',190,'choose capability (tool / data)'],['cli','app',220,'selection ack',1],
  ['app','cli',270,'invoke with parameters'],['cli','srv',300,'tools/call {name, arguments}'],['srv','ext',330,'perform action / query'],['ext','srv',370,'result / data',1],['srv','cli',400,'response (JSON-RPC result)',1],['cli','app',430,'structured content',1]];
 M.forEach(([f,t,y,l,d],i)=>{nodes.push(Object.assign(N('m'+i+'a',lx[f],y,0,0,'','','gray',''),{pt:1}),Object.assign(N('m'+i+'b',lx[t],y,0,0,'','','gray',''),{pt:1}));edges.push(E('m'+i+'a','m'+i+'b',{l,dash:d}));});
 nodes.push(N('proc',45,452,170,34,'Process','use the result','green','The LLM folds the result into its reasoning and either answers or makes another call.'));
 nodes.push(N('obs',290,492,670,30,'Observe · logs, metrics and audit across every hop','','pink','Trace every request and response: who called what, with which arguments, and what happened. This is the basis for evals and governance.'));
 const m=i=>'m'+i+'a>m'+i+'b';
 return {vb:[1000,540],nodes,edges,title:'MCP message flow',noSeq:1,steps:[
  {title:'Discover',e:[m(0),m(1)],t:'The client (optionally after <code>server/discover</code>) lists what the server offers: tools with JSON Schemas, resources and prompts. Since spec 2026-07-28 there is no initialize handshake; every request carries its version and capabilities.'},
  {title:'Select',e:[m(2),m(3)],t:'The model sees the tool list and picks one that fits the task.'},
  {title:'Request',e:[m(4),m(5),m(6)],t:'The client sends <code>tools/call</code>. The server performs the real action with its own credentials.'},
  {title:'Receive',e:[m(7),m(8),m(9)],t:'Results flow back as a JSON-RPC result with content blocks (text, JSON, images, resource links).'},
  {title:'Process',n:['proc'],t:'The LLM uses the result, then answers or loops: discover → select → request → receive → repeat.'},
  {title:'Observe',n:['obs'],t:'Logs, metrics and audit at every hop make MCP interactions consistent, secure and observable.'}]};})();

