DEFS.career=(()=>{const nodes=[Q('root',20,286,'What aspect of AI interests you most?','','blue','Start here.',160,64)],edges=[],steps=[];
 CAR.forEach(([p,q,rs],i)=>{const c=i*120+66;nodes.push(Q('p'+i,215,c-26,p,'','blue','Persona: '+p+'.',150,52));nodes.push(Q('q'+i,400,c-28,q,'','amber','Decision point.',210,56));
  edges.push(E('root','p'+i),E('p'+i,'q'+i));
  rs.forEach(([lab,role,sk],j)=>{const id='r'+i+j;nodes.push(Q(id,690,j?c+13:c-57,role,sk.slice(0,2).join(' · '),'green','Key skills: '+sk.join(', ')+'.',290,44));edges.push(E('q'+i,id,{l:lab}));
   steps.push({title:role,e:['root>p'+i,'p'+i+'>q'+i,'q'+i+'>'+id],t:`<b>${p}</b> → ${q} → <b>${lab}</b>. Key skills: ${sk.join(', ')}.`});});});
 return {vb:[1000,630],title:'AI career paths',nodes,edges,steps};})();

