 const P=[[30,118,104,104,{sh:'hub'}],[178,130,160,84,{badge:'check'}],[372,130,160,84,{badge:'check'}],[566,130,160,84,{badge:'up'}],[762,118,104,104,{sh:'hub',icon:'lines',lblTop:1}],[955,38,170,86,{badge:'plus'}],[955,206,170,86,{badge:'up'}]],C=['blue','blue','purple','orange','purple','blue','purple'];
