/* ---------- INIT FLOWS ---------- */
const stateOrder=['submitted','working','input-required','completed','failed','canceled'];
document.querySelectorAll('[data-flow]').forEach(h=>{
  const k=h.dataset.flow;let def=DEFS[k],opts={};
  if(k==='roles')def=roleDef(ROLES[0]);
  if(k==='patterns')def=PATS[0].def;
  if(k==='ragv')def=RAGV[0].def;
  if(k==='wf')def=WF[0].def;
  if(k==='ts')def=TS[0].def;
  if(k==='lt')def=LT[0].def;
  if(k==='lw')def=LW[0].def;
  if(k==='aieng')def=aiDef(0);
  if(k==='roles12')opts.onStep=(i,st)=>{if(st)roleCard(st.ri);};
  if(k==='rc')def=RC[0].def;
  if(k==='toolcall')opts.onStep=(i,st)=>tcState(st);
  if(k==='a2a')opts.onStep=(i,st)=>renderStates(st&&st.state);
  FLOWS[k]=new Flow(h,def,opts);
  h.dataset.section=h.closest('section').id;
});
function renderStates(cur){const box=document.getElementById('a2astates');const ci=stateOrder.indexOf(cur);
  box.innerHTML=stateOrder.map((s,i)=>`<span class="st ${s===cur?'on':(ci>=0&&i<ci&&i<4?'done':'')}">${s}</span>`).join('<span class="arrow">→</span>').replace(/<span class="arrow">→<\/span>(<span class="st[^"]*">failed)/,' <span class="muted" style="margin-left:10px">terminal:</span> $1');}
