const ul=a=>'<ul style="margin:0;padding-left:18px">'+a.map(x=>`<li>${x}</li>`).join('')+'</ul>';
if(document.getElementById("patterns")){document.getElementById('pattable').innerHTML='<tr><th></th>'+PATS.map(p=>`<th style="color:var(--${p.c})">${p.t.replace(' Engineering','')}</th>`).join('')+'</tr>'+
 [['Idea','tag'],['Purpose','purpose'],['Best for','best'],['Strengths','str'],['Limitations','lim'],['Example','ex']].map(([l,k])=>`<tr><td><b>${l}</b></td>${PATS.map(p=>`<td>${Array.isArray(p[k])?ul(p[k]):p[k]}</td>`).join('')}</tr>`).join('')+
 '<tr><td><b>Key takeaway</b></td><td colspan="3">Harness for empowerment. Loop for refinement. Graph for complexity. Choose the approach that fits the problem.</td></tr>';}

/* ---------- RAG PLAYGROUND ---------- */
const CH=[
 {s:'Playbooks',t:'P1 payments incident runbook: page on-call SRE within 5 min, open bridge, freeze deploys, notify payments lead.',v:.89,r:.95,rel:1},
 {s:'Past incident notes',t:'2026-03 payments outage: gateway timeouts from expired TLS cert; mitigation was failover to secondary PSP.',v:.84,r:.82,rel:1},
 {s:'Policies',t:'Customer comms policy: outages over 30 min need a status-page update every 30 min.',v:.81,r:.77,rel:1},
 {s:'Product docs',t:'Payments API retry semantics and idempotency keys.',v:.78,r:.48,rel:0},
 {s:'Past incident notes',t:'2025-11 email delivery outage caused by a DNS misconfiguration.',v:.75,r:.16,rel:0},
 {s:'Playbooks',t:'P2 minor degradation playbook: open a ticket, no paging required.',v:.73,r:.38,rel:0},
 {s:'Product docs',t:'Refund API: partial refunds and settlement timing.',v:.69,r:.11,rel:0},
 {s:'Policies',t:'On-call compensation and rotation policy.',v:.66,r:.07,rel:0}];
function rag(){const k=+rk.value,useR=rro.checked,thr=rt2.value/100;rkv.textContent=k;rtv.textContent=thr.toFixed(2);rt2.disabled=!useR;
  const top=CH.map((c,i)=>({...c,i})).slice(0,k);let ctx=useR?top.filter(c=>c.r>=thr).sort((a,b)=>b.r-a.r):top;const ids=new Set(ctx.map(c=>c.i));
  const rel=ctx.filter(c=>c.rel).length,noise=ctx.length-rel,tok=ctx.reduce((a,c)=>a+Math.round(c.t.length/3.6)+40,0);
  rstats.innerHTML=`<div class="stat"><b>${ctx.length}</b><span>chunks in prompt</span></div><div class="stat"><b>${rel}/3</b><span>relevant recalled</span></div><div class="stat"><b>${noise}</b><span>noise chunks</span></div><div class="stat"><b>~${tok}</b><span>context tokens</span></div>`;
  rchunks.innerHTML=CH.map((c,i)=>{const inT=i<k,inC=ids.has(i);return `<div class="chunk ${inC?'in':(inT?'':'out')}"><div style="flex:1"><span class="tag">${c.s}</span> ${c.rel?'<span class="pill" style="color:var(--green)">✓ relevant</span>':''}<br>${c.t}</div><div class="sc">sim ${c.v.toFixed(2)}<br>${useR?'rerank '+c.r.toFixed(2):''}<br>${inC?'<b style="color:var(--accent)">IN PROMPT</b>':inT?'<span>filtered</span>':'<span>not retrieved</span>'}</div></div>`;}).join('');
  rhint.innerHTML=rel<3&&k<3?'<b>Recall problem:</b> k is too small, so relevant chunks never reach the reranker. The LLM will answer with gaps or guess.':
   noise>1?'<b>Precision problem:</b> irrelevant chunks dilute the context and cost tokens. Turn on reranking or raise the threshold.':
   rel===3&&noise===0?'<b>Sweet spot:</b> retrieve broadly, then rerank and filter tightly. All relevant context goes in, with no noise.':
   rel<3?'<b>Over-filtered:</b> the threshold is cutting relevant chunks. Lower it a bit.':'Good balance. Try other settings to see the trade-off.';}
const rk=document.getElementById('rk'),rro=document.getElementById('rro'),rt2=document.getElementById('rt'),rkv=document.getElementById('rkv'),rtv=document.getElementById('rtv'),rstats=document.getElementById('rstats'),rchunks=document.getElementById('rchunks'),rhint=document.getElementById('rhint');
if(document.getElementById("rag")){[rk,rro,rt2].forEach(x=>x.oninput=rag);}if(document.getElementById("rag")){rag();}

/* ---------- AUTONOMY ---------- */
const LV=[['Assist','The agent proposes and the human executes. Only reads run on their own.'],['Approve every write','Reads run automatically. Every state change waits for approval.'],['Approve external & irreversible','Internal writes run automatically. Spending, messaging externally and deleting wait for approval.'],['Notify, approve destructive','Most actions run and notify the user. Only destructive or high-value actions wait.'],['Fully autonomous','Everything runs. Rely on audit logs, budgets and a fail-closed risk kernel.']];
const ACT=[['Search flights','read',0],['Read calendar & preferences','read',0],['Add calendar event','internal write',1],['Book ticket ($640)','spend money',2],['Email confirmation to traveler','external message',2],['Cancel an existing booking','destructive',3]];
const al=document.getElementById('al');
function auto(){const L=+al.value;document.getElementById('alv').textContent=L+' · '+LV[L][0];document.getElementById('ald').textContent=LV[L][1];
  document.getElementById('alt').innerHTML=ACT.map(([a,kind,r])=>{let s;
    if(L===0)s=r===0?['auto','Auto']:['human','Human does it'];else if(L===1)s=r===0?['auto','Auto']:['appr','Needs approval'];else if(L===2)s=r<=1?['auto','Auto']:['appr','Needs approval'];else if(L===3)s=r<=2?['auto',r===2?'Auto + notify':'Auto']:['appr','Needs approval'];else s=['auto','Auto + logged'];
    return `<div>${a} <span class="pill">${kind}</span></div><span class="badge ${s[0]}">${s[1]}</span>`;}).join('');}
if(document.getElementById("agents")){al.oninput=auto;}if(document.getElementById("agents")){auto();}

/* ---------- MCP calc ---------- */
const mm=document.getElementById('mm'),mn=document.getElementById('mn');
function mcalc(){document.getElementById('mmv').textContent=mm.value;document.getElementById('mnv').textContent=mn.value;document.getElementById('mx').textContent=(mm.value*mn.value).toLocaleString();document.getElementById('mp').textContent=(+mm.value + +mn.value).toLocaleString();}
if(document.getElementById("mcp")){mm.oninput=mn.oninput=mcalc;}if(document.getElementById("mcp")){mcalc();}

/* ---------- LOOP SIM ---------- */
function rnd(seed){return()=>{seed=(seed*16807)%2147483647;return seed/2147483647;};}
function loop(){const bar=+lq.value,mx=+li.value,q0=+l0.value;lqv.textContent=bar;liv.textContent=mx;l0v.textContent=q0;
  const R=rnd(bar*31+mx*7+q0);let q=q0,arr=[];for(let i=0;i<mx;i++){if(i>0)q=Math.min(99,q+(100-q)*(0.28+R()*0.14)-R()*2);arr.push(Math.round(q));if(q>=bar)break;}
  const hit=arr[arr.length-1]>=bar;
  lbars.innerHTML=`<div class="thr" style="bottom:${bar*1.5+10}px"><span>bar ${bar}</span></div>`+arr.map(v=>`<div class="bar ${v>=bar?'hit':''}" style="height:${v*1.5}px"><span>${v}</span></div>`).join('');
  lres.innerHTML=hit?`<b style="color:var(--green)">Stopped: quality bar met</b> after ${arr.length} iteration${arr.length>1?'s':''}. Gains shrink each round, which is typical of refinement loops.`:
   `<b style="color:var(--pink)">Stopped: budget exhausted</b> at ${arr[arr.length-1]} after ${mx} iteration${mx>1?'s':''}. Without a max-iterations cap, this loop could run indefinitely. Raise the budget, lower the bar, or improve the first draft.`;}
const lq=document.getElementById('lq'),li=document.getElementById('li'),l0=document.getElementById('l0'),lqv=document.getElementById('lqv'),liv=document.getElementById('liv'),l0v=document.getElementById('l0v'),lbars=document.getElementById('lbars'),lres=document.getElementById('lres');
if(document.getElementById("patterns")){[lq,li,l0].forEach(x=>x.oninput=loop);}if(document.getElementById("patterns")){document.getElementById('lrun').onclick=loop;}if(document.getElementById("patterns")){loop();}

/* chooser */
function choose(){const a=q1.checked,b=q2.checked,c=q3.checked;let rec,why;
  if(c){rec='Graph engineering'+(b?' with loops inside nodes':'');why='Specialists with different tools or permissions are best expressed as nodes with explicit routing.'+(b?' Add evaluator loops inside the nodes that need refinement.':'')+' Start with the fewest nodes that work.';}
  else if(a){rec='Agent harness'+(b?' + an evaluation loop':'');why='One well-equipped agent is the simplest reliable option.'+(b?' Wrap its output in a draft → evaluate → refine loop with a clear stop condition.':' Invest in tools, context and guardrails before adding more agents.');}
  else{rec=b?'Loop engineering, then split if it outgrows one context':'Harness first, then split into a graph when context or permissions force it';why='If one agent can\'t hold the whole task, decompose it. But don\'t add orchestration overhead before you need it.';}
  qrec.textContent='→ '+rec;qwhy.textContent=why;}
const q1=document.getElementById('q1'),q2=document.getElementById('q2'),q3=document.getElementById('q3'),qrec=document.getElementById('qrec'),qwhy=document.getElementById('qwhy');
if(document.getElementById("patterns")){[q1,q2,q3].forEach(x=>x.onchange=choose);}if(document.getElementById("patterns")){choose();}

/* ---------- OPTIMIZATION ---------- */
const CAT={finetune:['Fine-tuning','purple'],knowledge:['Knowledge','orange'],compress:['Compression','teal'],inference:['Inference','blue'],arch:['Architecture','pink']};
const OPT=[
 {n:'PEFT',f:'Parameter-Efficient Fine-Tuning',cat:'finetune',what:'Fine-tune only small parts of the model (adapters, prefixes, low-rank updates) instead of the full model.',ben:'Lower cost, less memory, faster training. One base model can serve many task adapters.',trade:'Can trail full fine-tuning on tasks far from the base model\'s training data.',lv:['cost','memory']},
 {n:'LoRA',f:'Low-Rank Adaptation',cat:'finetune',what:'Adds lightweight trainable matrices A (d×r) and B (r×d). The weight update BA has rank r, much smaller than d.',ben:'Efficient fine-tuning, often with under 1% trainable params. Adapters can be merged into the weights, adding no latency.',trade:'Rank and target-module choices matter. Too low a rank underfits.',lv:['cost','memory'],calc:1},
 {n:'QLoRA',f:'Quantized Low-Rank Adaptation',cat:'finetune',what:'Freezes the base model in 4-bit and trains LoRA adapters on top in higher precision.',ben:'Even lower memory use with high performance. Large models can be fine-tuned on a single GPU.',trade:'Slower steps because of de-quantization, and a small quality gap in some cases.',lv:['memory','cost']},
 {n:'RAG',f:'Retrieval-Augmented Generation',cat:'knowledge',what:'Fetches external knowledge dynamically instead of retraining the model.',ben:'More accurate, up-to-date and context-aware answers, with citations.',trade:'Quality is capped by retrieval quality, and it adds latency and tokens.',lv:['quality','freshness'],link:'rag'},
 {n:'Quantization',f:'16-bit → 8-bit → 4-bit',cat:'compress',what:'Reduces the numeric precision of weights (and sometimes activations or KV cache) to cut memory and improve speed.',ben:'Smaller model size and faster inference, often 2–4× less memory.',trade:'Accuracy can drop at 4-bit and below. Needs good calibration methods (GPTQ, AWQ and others).',lv:['memory','latency','cost'],calc:0},
 {n:'Distillation',f:'Knowledge Distillation',cat:'compress',what:'Trains a smaller "student" model using a larger "teacher" model\'s outputs.',ben:'Faster, smaller models that keep good performance on target tasks.',trade:'Needs teacher compute and data, and the student rarely beats the teacher.',lv:['latency','cost']},
 {n:'Pruning',f:'Remove weights / neurons',cat:'compress',what:'Removes unnecessary weights, heads or layers to make models smaller and faster, usually followed by brief retraining.',ben:'Reduced model size and faster inference.',trade:'Unstructured sparsity only speeds things up on kernels and hardware that exploit it.',lv:['memory','latency']},
 {n:'Flash Attention',f:'IO-aware exact attention',cat:'inference',what:'An optimized attention kernel that works in tiles in fast on-chip memory and never builds the full N×N matrix.',ben:'Higher throughput and lower memory use with identical results. Enables long contexts.',trade:'GPU-specific kernels, and the gains depend on hardware generation.',lv:['latency','memory']},
 {n:'KV Cache',f:'Key-Value Cache',cat:'inference',what:'Reuses previously computed attention keys and values so each new token doesn\'t recompute the whole prefix.',ben:'Faster generation and lower compute cost.',trade:'Memory grows with sequence length × batch size, and is often the real serving bottleneck.',lv:['latency'],calc:2},
 {n:'MoE',f:'Mixture of Experts',cat:'arch',what:'A router activates only a few expert sub-networks per token instead of the entire model.',ben:'Higher efficiency and scalability with fewer active parameters.',trade:'All experts must still fit in memory, and routing and load balancing add complexity.',lv:['cost','quality']}];
const BONUS=[['Prompt optimization','Better prompts mean better outputs at lower cost.'],['Context window management','Trim, summarize or chunk long inputs.'],['Batching','Process multiple requests together for efficiency (continuous batching).'],['Speculative decoding','A small draft model proposes tokens and the large model verifies several at once.'],['Hardware optimization','GPUs, TPUs, optimized kernels and efficient serving.'],['Model serving & caching','Optimize serving, prefix and semantic caching, and load balancing.']];
const optf=document.getElementById('optf'),optgrid=document.getElementById('optgrid');let curCat='all';
function renderOpt(){[...optf.children].forEach(b=>b.classList.toggle('on',b.dataset.k===curCat));
  optgrid.innerHTML=OPT.map((o,i)=>({o,i})).filter(({o})=>curCat==='all'||o.cat===curCat).map(({o,i})=>{const [cn,cc]=CAT[o.cat];return `<div class="card opt" style="--c:var(--${cc})" data-i="${i}" tabindex="0">
  <h3>${i+1}. ${o.n}<small>${o.f}</small></h3><div class="muted" style="font-size:14px">${o.what}</div>
  <div class="meta"><span class="pill" style="color:var(--${cc})">${cn}</span>${o.lv.map(l=>`<span class="pill">↓ ${l==='quality'||l==='freshness'?'↑ '+l:l}</span>`).join('').replace(/↓ ↑/g,'↑')}</div>
  <div class="more"><p style="margin:0 0 6px"><b>Benefit:</b> ${o.ben}</p><p style="margin:0"><b>Trade-off:</b> ${o.trade}</p>${o.link?`<p style="margin:6px 0 0"><a href="#${o.link}">See the interactive RAG flow →</a></p>`:''}${o.calc!==undefined?`<p style="margin:6px 0 0"><a href="#optimization" data-calc="${o.calc}">Open calculator ↓</a></p>`:''}</div></div>`;}).join('');}
if(document.getElementById("optimization")){[['all','All']].concat(Object.entries(CAT).map(([k,v])=>[k,v[0]])).forEach(([k,l])=>{const b=document.createElement('button');b.className='tab';b.dataset.k=k;b.textContent=l;b.onclick=()=>{curCat=k;renderOpt();};optf.appendChild(b);});}
if(document.getElementById("optimization")){optgrid.addEventListener('click',e=>{const a=e.target.closest('[data-calc]');if(a){e.preventDefault();pickCalc(+a.dataset.calc);document.getElementById('calc').scrollIntoView({behavior:'smooth',block:'center'});return;}
  if(e.target.closest('a'))return;const c=e.target.closest('.opt');if(c)c.classList.toggle('open');});}
if(document.getElementById("optimization")){optgrid.addEventListener('keydown',e=>{if(e.key==='Enter'){const c=e.target.closest('.opt');if(c)c.classList.toggle('open');}});}
if(document.getElementById("optimization")){renderOpt();}
if(document.getElementById("optimization")){document.getElementById('bonus').innerHTML=BONUS.map(([t,d])=>`<div class="card"><h3>${t}</h3><p class="muted" style="margin:0">${d}</p></div>`).join('');}

/* calculators */
const calcEl=document.getElementById('calc'),ct=document.getElementById('calctabs');
const CALCS=[
 {t:'Quantization memory',html:`<div class="ctlrow"><label>Model size (B params) <input type="range" id="qp" min="1" max="405" value="70"><input type="number" id="qpn" min="1" max="2000" value="70"></label>
  <label>Presets <select id="qps"><option value="">—</option><option>7</option><option>8</option><option>13</option><option>34</option><option>70</option><option>405</option></select></label></div><div id="qout"></div>`,
  init(){const p=qs('#qp'),n=qs('#qpn'),s=qs('#qps');const f=v=>{p.value=Math.min(405,v);n.value=v;const P=+v;
    const rows=[[32,'FP32'],[16,'FP16 / BF16'],[8,'INT8 / FP8'],[4,'INT4 / NF4']].map(([b,l])=>[l,P*b/8]);const mx=rows[0][1];
    qs('#qout').innerHTML=rows.map(([l,g])=>`<div class="memrow"><span>${l}</span><div class="membar" style="width:${Math.max(2,g/mx*100)}%"></div><b class="mono">${g<10?g.toFixed(1):Math.round(g)} GB</b></div>`).join('')+
    `<p class="muted" style="margin:10px 0 0">Weights only: params × bits ÷ 8. A ${P}B model drops from <b>${Math.round(P*2)} GB</b> at 16-bit to <b>${Math.round(P/2)} GB</b> at 4-bit, which ${P/2<=24?'fits a single 24 GB GPU':P/2<=80?'fits a single 80 GB GPU':'still needs multiple GPUs'}.</p>`;};
   p.oninput=()=>f(+p.value);n.oninput=()=>f(Math.max(1,+n.value||1));s.onchange=()=>s.value&&f(+s.value);f(70);}},
 {t:'LoRA trainable params',html:`<div class="ctlrow"><label>Hidden size d <select id="ld"><option>2048</option><option selected>4096</option><option>5120</option><option>8192</option></select></label>
  <label>Layers <input type="number" id="ll" value="32" min="1" max="200"></label><label>Rank r <select id="lr"><option>4</option><option selected>8</option><option>16</option><option>32</option><option>64</option><option>128</option></select></label>
  <label>Target matrices / layer <select id="lm"><option value="2" selected>2 (q, v)</option><option value="4">4 (q, k, v, o)</option></select></label><label>Base model (B) <input type="number" id="lb" value="7" min="0.1" step="0.1"></label></div><div id="lout"></div>`,
  init(){const f=()=>{const d=+qs('#ld').value,L=+qs('#ll').value,r=+qs('#lr').value,m=+qs('#lm').value,B=+qs('#lb').value*1e9;const p=L*m*2*d*r;
    qs('#lout').innerHTML=`<div class="stats"><div class="stat"><b>${(p/1e6).toFixed(2)} M</b><span>trainable params</span></div><div class="stat"><b>${(p/B*100).toFixed(3)}%</b><span>of the base model</span></div><div class="stat"><b>${(p*2/1e6).toFixed(0)} MB</b><span>adapter file (fp16)</span></div></div>
    <p class="muted" style="margin:0">Per square d×d matrix, LoRA trains d·r + r·d = 2dr parameters instead of d². Formula: layers × matrices × 2 × d × r (assumes square attention projections).</p>`;};
   ['#ld','#ll','#lr','#lm','#lb'].forEach(s=>qs(s).oninput=f);f();}},
 {t:'KV cache size',html:`<div class="ctlrow"><label>Layers <input type="number" id="kl" value="32"></label><label>KV heads <input type="number" id="kh" value="8"></label><label>Head dim <input type="number" id="kd" value="128"></label>
  <label>Precision <select id="kb"><option value="2">FP16 (2 B)</option><option value="1">FP8 (1 B)</option></select></label></div>
  <div class="ctlrow"><label>Context length <input type="range" id="ks" min="0" max="7" value="3"><span class="out" id="ksv"></span></label><label>Concurrent sequences <input type="range" id="kn" min="1" max="64" value="8"><span class="out" id="knv"></span></label></div><div id="kout"></div>`,
  init(){const S=[1024,2048,4096,8192,16384,32768,65536,131072];const f=()=>{const L=+qs('#kl').value,h=+qs('#kh').value,d=+qs('#kd').value,b=+qs('#kb').value,s=S[+qs('#ks').value],n=+qs('#kn').value;
    qs('#ksv').textContent=(s/1024)+'k';qs('#knv').textContent=n;const per=2*L*h*d*b,tot=per*s*n;
    qs('#kout').innerHTML=`<div class="stats"><div class="stat"><b>${(per/1024).toFixed(0)} KB</b><span>per token</span></div><div class="stat"><b>${(per*s/2**30).toFixed(2)} GB</b><span>per sequence</span></div><div class="stat"><b class="big" style="font-size:22px">${(tot/2**30).toFixed(1)} GB</b><span>total KV cache</span></div></div>
    <p class="muted" style="margin:0">2 (K and V) × layers × KV heads × head dim × bytes, per token. Defaults resemble an 8B model with grouped-query attention. This is why long contexts and high concurrency are limited by memory: paged attention, KV quantization and prefix caching attack this number.</p>`;};
   ['#kl','#kh','#kd','#kb','#ks','#kn'].forEach(s=>qs(s).oninput=f);f();}}];
function qs(s){return calcEl.querySelector(s);}
function pickCalc(i){[...ct.children].forEach((b,j)=>b.classList.toggle('on',i===j));calcEl.innerHTML=CALCS[i].html;CALCS[i].init();}
