/* MCP file system example */
const FS=[
 ['list_files',{path:'/workspace/src'},{content:[{type:'text',text:'app.ts\nroutes/\nutils.ts'}]},'read','Safe read. Restrict it to declared roots.'],
 ['read_file',{path:'/workspace/README.md'},{content:[{type:'text',text:'# Payments Service\nRun `npm test` before…'}]},'read','Safe read, but watch for secrets (.env) and keep reads inside roots.'],
 ['write_file',{path:'/workspace/src/utils.ts',content:'export const retry = …'},{content:[{type:'text',text:'Wrote 1,284 bytes to src/utils.ts'}]},'write','State change. Log it, scope it to roots, and consider approval outside the project.'],
 ['search_files',{query:'TODO(security)'},{content:[{type:'text',text:'src/auth.ts:42  TODO(security): rotate key'}]},'read','Read. Cap the result size so it doesn\'t flood the context.'],
 ['delete_file',{path:'/workspace/tmp/cache.json'},{content:[{type:'text',text:'Deleted tmp/cache.json'}],isError:false},'destructive','Destructive. Require human approval, allow-list paths, audit every call.']];
const fsb=document.getElementById('fsbtns'),fso=document.getElementById('fsout');
function fsPick(i){const [n,args,res,risk,gov]=FS[i];[...fsb.children].forEach((b,j)=>b.classList.toggle('on',i===j));
  const req={jsonrpc:'2.0',id:i+7,method:'tools/call',params:{name:n,arguments:args}},rsp={jsonrpc:'2.0',id:i+7,result:res};
  const cls=risk==='read'?'auto':risk==='write'?'appr':'human';
  fso.innerHTML=`<div class="grid g2" style="margin-top:12px"><div><b>→ Request</b> <span class="muted">client → server</span><pre class="code">${esc(JSON.stringify(req,null,2))}</pre></div><div><b>← Response</b> <span class="muted">server → client</span><pre class="code">${esc(JSON.stringify(rsp,null,2))}</pre></div></div>
  <p style="margin:12px 0 0"><span class="badge ${cls}" style="${risk==='destructive'?'background:color-mix(in srgb,var(--pink) 15%,transparent);color:var(--pink)':''}">${risk}</span> <span class="muted">${gov}</span></p>`;}
if(document.getElementById("mcp-protocol")){FS.forEach((f,i)=>{const b=document.createElement('button');b.className='tab toolbtn';b.textContent=f[0]+'()';b.onclick=()=>fsPick(i);fsb.appendChild(b);});}if(document.getElementById("mcp-protocol")){fsPick(1);}

/* Hook simulator */
const HS=[
 {l:'Claude runs rm -rf ./build /',ev:'PreToolUse',tool:'Bash',m:'matcher "Bash" ✓',cmd:'block-dangerous.sh → exit 2',out:'Blocked. The command never runs, and stderr ("refusing recursive delete of /") goes back to Claude so it can adjust.',blk:1},
 {l:'Claude runs npm test',ev:'PreToolUse',tool:'Bash',m:'matcher "Bash" ✓',cmd:'block-dangerous.sh → exit 0',out:'Allowed. The hook inspected the command and found nothing dangerous.'},
 {l:'Claude writes src/app.ts',ev:'PostToolUse',tool:'Write',m:'matcher "Write|Edit" ✓',cmd:'eslint --fix src/app.ts',out:'Auto-lint on write. Formatting is guaranteed even if the model forgets.'},
 {l:'Session starts',ev:'SessionStart',tool:'—',m:'no matcher needed',cmd:'load-context.sh',out:'Its output (current branch, open TODOs) is added to the session context.'},
 {l:'Claude finishes its turn',ev:'Stop',tool:'—',m:'no matcher needed',cmd:'notify-slack.sh',out:'Slack notification on stop: "Claude finished: tests passing on feature/retry".'},
 {l:'code-reviewer subagent finishes',ev:'SubagentStop',tool:'—',m:'no matcher needed',cmd:'log-subagent.sh',out:'The subagent\'s result is logged for audit and evals.'},
 {l:'Claude reads a file',ev:'PreToolUse',tool:'Read',m:'no matcher for "Read" ✗',cmd:'(nothing runs)',out:'No hook matched, so the tool runs normally. Hooks only fire where you point them.',miss:1}];
const hb=document.getElementById('hookbtns'),hp=document.getElementById('hookpipe'),hr=document.getElementById('hookres');let htimers=[];
function hookRun(i){const h=HS[i];[...hb.children].forEach((b,j)=>b.classList.toggle('on',i===j));htimers.forEach(clearTimeout);htimers=[];
  const cells=[['Event fires',h.ev+(h.tool!=='—'?' · '+h.tool:'')],['Matcher checks',h.m],['Command runs',h.cmd],['Outcome',h.blk?'⛔ blocked':h.miss?'pass-through':'✓ done']];
  hp.innerHTML=cells.map(([a,b])=>`<div><b>${a}</b><span class="mono">${esc(b)}</span></div>`).join('');hr.textContent='';
  [...hp.children].forEach((c,k)=>htimers.push(setTimeout(()=>{if(h.miss&&k>=2)return;c.classList.add(h.blk&&k===3?'blk':'lit');if(k===3||(h.miss&&k===1))hr.innerHTML=h.out;},250+k*450)));
  if(h.miss)htimers.push(setTimeout(()=>hr.innerHTML=h.out,1200));}
if(document.getElementById("agent-kit")){HS.forEach((h,i)=>{const b=document.createElement('button');b.className='tab';b.textContent=h.l;b.onclick=()=>hookRun(i);hb.appendChild(b);});}if(document.getElementById("agent-kit")){hookRun(0);}

