function pickTS(i){const t=TS[i];[...tst.children].forEach((b,j)=>b.classList.toggle('on',i===j));FLOWS.ts.load(t.def);
  tsd.innerHTML=`<div class="card"><h3>${t.t}</h3><p class="muted" style="margin:0">${t.d}</p></div><div class="card"><h3>Used in</h3><p class="muted" style="margin:0">${t.use}</p></div><div class="card"><h3>Watch out</h3><p class="muted" style="margin:0">${t.watch}</p></div>`;}
