function tlat(){const v=[1,2,3].map(i=>+document.getElementById('tl'+i).value),h=+document.getElementById('tlh').value/100;
  [1,2,3].forEach((i,k)=>document.getElementById('tl'+i+'v').textContent=v[k]+'ms');document.getElementById('tlhv').textContent=Math.round(h*100)+'%';
  const seq=v.reduce((a,b)=>a+b,0),par=Math.max(...v),cache=Math.round(h*20+(1-h)*par),mx=seq;
  const row=(l,ms,c,n)=>`<div class="memrow" style="grid-template-columns:150px 1fr 80px"><span>${l}</span><div class="membar" style="width:${Math.max(1,ms/mx*100)}%;background:var(--${c})"></div><b class="mono">${ms} ms</b></div><div class="muted" style="font-size:12.5px;margin:-2px 0 8px 160px">${n}</div>`;
  document.getElementById('tlout').innerHTML=row('Chained (sequential)',seq,'gray','sum of all calls')+row('Parallel',par,'green','the slowest call')+row('Parallel + cache',cache,'amber',`expected: ${Math.round(h*100)}% hits at ~20 ms, misses fall back to parallel`);}
if(document.getElementById("tool-call")){[1,2,3].forEach(i=>document.getElementById('tl'+i).oninput=tlat);}if(document.getElementById("tool-call")){document.getElementById('tlh').oninput=tlat;}if(document.getElementById("tool-call")){tlat();}
/* voice layers */
if(document.getElementById("voice")){document.getElementById('vlayers').innerHTML=VL.map(([n,t,q,c,items])=>`<div class="card" style="display:grid;grid-template-columns:170px 1fr;gap:14px;align-items:center;margin-bottom:10px;border-left:4px solid var(--${c})"><div><span class="muted" style="font-size:12.5px">${q}</span><h3 style="margin:2px 0 0;color:var(--${c})">${n} · ${t}</h3></div><div>${items.map(i=>`<span class="pill" style="font-size:12.5px;padding:5px 10px">${i}</span>`).join('')}</div></div>`).join('')+'<div class="callout">A good voice agent is not just a voice. It is a connected business system.</div>';}
const vlc=document.getElementById('vlctl'),VCOL=['gray','teal','amber','blue','green'];
if(document.getElementById("voice")){vlc.innerHTML=VLAT.map(([l,mn,mx,v],i)=>`<label>${l} <input type="range" id="vl${i}" min="${mn}" max="${mx}" step="10" value="${v}"><span class="out" id="vl${i}v"></span></label>`).join('');}
function vlat(){const vals=VLAT.map((_,i)=>+document.getElementById('vl'+i).value);vals.forEach((v,i)=>document.getElementById('vl'+i+'v').textContent=v+'ms');const tot=vals.reduce((a,b)=>a+b,0);
  document.getElementById('vlbar').innerHTML=vals.map((v,i)=>v?`<div title="${VLAT[i][0]}" style="flex:${v};background:var(--${VCOL[i]});color:#fff;font:600 11px Inter;display:grid;place-items:center;overflow:hidden;white-space:nowrap">${v>=120?VLAT[i][0].split(' ')[0]:''}</div>`:'').join('');
  const [col,msg]=tot<=800?['green','Feels natural. Callers rarely notice the gap.']:tot<=1500?['amber','Noticeable pause. Add a short spoken acknowledgement or stream sooner.']:['pink','Awkward. Callers will talk over the agent or assume it dropped. Cut the slowest stage.'];
  document.getElementById('vlres').innerHTML=`<b style="color:var(--${col});font-size:20px">${tot} ms</b> to first audio · <span class="muted">${msg}</span>`;}
if(document.getElementById("voice")){VLAT.forEach((_,i)=>document.getElementById('vl'+i).oninput=vlat);}if(document.getElementById("voice")){vlat();}
