const cq=document.getElementById('cquiz');
function cqRender(p,b){let h='<h3>1 · What aspect of AI interests you most?</h3><div class="scen">'+CAR.map((c,i)=>`<button class="tab ${p===i?'on':''}" data-p="${i}">${c[0]}</button>`).join('')+'</div>';
  if(p!=null)h+=`<h3 style="margin-top:14px">2 · ${CAR[p][1]}</h3><div class="scen">`+CAR[p][2].map((r,j)=>`<button class="tab ${b===j?'on':''}" data-b="${j}">${r[0]}</button>`).join('')+'</div>';
  if(b!=null){const [,role,sk]=CAR[p][2][b];h+=`<div class="callout" style="margin-bottom:0"><span class="muted">Your path</span><div class="rec">${role}</div><div style="margin-top:6px">${sk.map(s=>`<span class="pill">${s}</span>`).join('')}</div></div>`;FLOWS.career.go(p*2+b);}
  cq.innerHTML=h;cq.querySelectorAll('[data-p]').forEach(x=>x.onclick=()=>cqRender(+x.dataset.p,null));cq.querySelectorAll('[data-b]').forEach(x=>x.onclick=()=>cqRender(p,+x.dataset.b));}
