/* builder */
if(document.getElementById("prompt-eng")){(function(){const f=document.getElementById('pbform'),o=document.getElementById('pbout');let V={task:'Give me some content ideas.'};
 function r(){f.innerHTML=PEL.map(([k,t,q],i)=>`<label style="display:block;margin-bottom:8px"><b style="font-size:13px;color:var(--${PEL[i][4]})">${i+1} · ${t}</b> <span class="muted" style="font-size:12px">${q}</span><input type="text" data-k="${k}" value="${esc(V[k]||'').replace(/"/g,'&quot;')}" placeholder="${esc(PEL[i][3]).replace(/"/g,'&quot;')}" style="display:block;width:100%;margin-top:3px;font:inherit;font-size:14px;padding:7px 10px;border-radius:8px;border:1px solid var(--line);background:var(--bg);color:var(--ink)"></label>`).join('');
  f.querySelectorAll('input').forEach(x=>x.oninput=()=>{V[x.dataset.k]=x.value;out();});out();}
 function out(){const g=k=>(V[k]||'').trim();const pre={role:'',goal:'',context:'Context: ',task:'',constraints:'Constraints: ',format:'Format: ',example:'Example of what I want: '};
  o.textContent=PEL.map(([k])=>g(k)?pre[k]+g(k):'').filter(Boolean).join('\n')||'(empty)';const n=PEL.filter(([k])=>g(k)).length;
  const col=n>=5?'green':n>=3?'amber':'pink';document.getElementById('pbscore').innerHTML=`<span style="color:var(--${col})">${n}/7 elements</span>`;
  const miss=PEL.filter(([k])=>!g(k)).map(([,t])=>t);
  document.getElementById('pbwhy').innerHTML=n<=1?'<p style="margin:0"><b style="color:var(--pink)">Weak prompt: leaves the AI guessing.</b> Too little context, no audience, no clear goal, no quantity, no format, no quality criteria.</p>':`<p style="margin:0 0 6px">${[g('context')&&'<b>More context</b> → better relevance',g('task')&&/\d/.test(g('task'))&&'<b>Clearer task</b> → less ambiguity',g('format')&&'<b>Defined format</b> → easier-to-use output',g('constraints')&&'<b>Explicit constraints</b> → fewer unwanted results',g('role')&&'<b>Role</b> → the right perspective',g('example')&&'<b>Example</b> → consistent style'].filter(Boolean).join('<br>')}</p>${miss.length?`<p class="muted" style="margin:0;font-size:13px">Not set: ${miss.join(', ')}. Add one only if it would actually change the answer.</p>`:''}`;}
 document.getElementById('pbstrong').onclick=()=>{V={};PEL.forEach(([k,,,ex])=>V[k]=ex);r();};document.getElementById('pbweak').onclick=()=>{V={task:'Give me some content ideas.'};r();};
 copyBtn(document.getElementById('pbcopy'),()=>o.textContent,'Copy');r();})();}
/* checker */
if(document.getElementById("prompt-eng")){(function(){const i=document.getElementById('pcin'),o=document.getElementById('pcout');
 const T=[['Role','act as|you are|as an? (expert|senior|strategist|analyst|writer|teacher)','Add a role: "Act as a…"'],['Specific task with a quantity','\\b(\\d+|three|five|ten)\\b.*\\b(ideas|steps|ways|options|points|paths|examples|bullets|questions)|\\b(ideas|steps|ways|options|points|paths)\\b.*\\b\\d+','Say how many: "5 ideas", "3 options"'],['Audience','\\bfor (a |an |my |our )?(beginner|student|team|manager|customer|executive|developer|kid|user|reader|founder)|audience|beginners','Who is it for?'],['Context / background','\\b(i am|i\'m|we are|we\'re|our|my|context|background)\\b','Give a line of background'],['Constraints','\\b(under|less than|no more than|avoid|don\'t|do not|keep|limit|only|must|max)\\b|\\bwords\\b','Add limits: length, tone, exclusions'],['Output format','\\b(table|bullet|list|json|outline|steps|checklist|headings|columns|markdown|paragraph)\\b','Say what shape the answer should take'],['Example','\\b(e\\.g\\.|for example|example|like this|such as)\\b','Optional: show what good looks like'],['Success / verification','\\b(cite|source|verify|check|if (anything is )?unclear|ask me|criteria|should include)\\b','Optional: how to judge or check it']];
 function r(){const t=i.value.toLowerCase();const res=T.map(([n,re,tip])=>[n,new RegExp(re,'i').test(t),tip]);const ok=res.filter(x=>x[1]).length,w=t.split(/\s+/).filter(Boolean).length;
  const col=ok>=6?'green':ok>=3?'amber':'pink';
  o.innerHTML=`<div class="ctlrow" style="margin:0 0 8px"><b style="font-size:20px;color:var(--${col})">${ok}/8</b><span class="muted">${w} words · ${ok>=6?'clear brief':ok>=3?'getting there':'the AI will be guessing'}</span></div><div class="grid g2" style="gap:4px 14px">${res.map(([n,y,tip])=>`<div style="font-size:14px">${y?'<span style="color:var(--green)">✓</span>':'<span style="color:var(--pink)">✗</span>'} <b>${n}</b>${y?'':` <span class="muted">· ${tip}</span>`}</div>`).join('')}</div>${w>250?'<p class="muted" style="margin:8px 0 0">Long prompt: check that every instruction earns its place.</p>':''}`;}
 i.oninput=r;r();})();}
if(document.getElementById("prompt-eng")){document.getElementById('ptech').innerHTML='<tr><th>#</th><th>Technique</th><th>Purpose</th><th>Example</th></tr>'+PTECH.map(([t,p,e],i)=>`<tr><td>${i+1}</td><td><b>${t}</b></td><td><span class="pill" style="color:var(--blue)">${p}</span></td><td class="muted">${esc(e)}</td></tr>`).join('');}
