/* debugger */
if(document.getElementById("prompt-debug")){(function(){const s=document.getElementById('pdsym'),o=document.getElementById('pdout');
 s.innerHTML=PDS.map(([n],i)=>`<button class="tab" data-i="${i}">${n}</button>`).join('');
 s.querySelectorAll('button').forEach(b=>b.onclick=()=>{s.querySelectorAll('button').forEach(x=>x.classList.toggle('on',x===b));const [n,c,f,k]=PDS[+b.dataset.i];
  o.innerHTML=`<div class="grid g3"><div class="card" style="box-shadow:none;background:var(--soft)"><h3>Likely cause</h3><p style="margin:0">${c}</p></div><div class="card" style="box-shadow:none;background:color-mix(in srgb,var(--green) 10%,var(--panel))"><h3 style="color:var(--green)">Smallest useful fix</h3><p style="margin:0">${f}</p></div><div class="card" style="box-shadow:none;background:var(--soft)"><h3>Check</h3><p style="margin:0">${k}</p></div></div>`;});s.querySelector('button').click();
 document.getElementById('pdmist').innerHTML=PDM.map(([n,p,f],i)=>`<div class="card" style="border-left:4px solid var(--orange)"><h3>${String(i+1).padStart(2,'0')} · ${n}</h3><p style="margin:0 0 4px;font-size:14px"><b style="color:var(--pink)">${i?'Problem':'Weak'}:</b> ${esc(p)}</p><p style="margin:0;font-size:14px"><b style="color:var(--green)">${i?'Fix':'Better'}:</b> ${esc(f)}</p></div>`).join('');
 const S={o:[3,2,3,2,3],v:[4,4,4,5,4]};const t=document.getElementById('pdeval');
 function r(){t.innerHTML='<tr><th>Criterion</th><th>What to check</th><th>Original</th><th>Revised</th></tr>'+PDE.map(([c,w],i)=>`<tr><td><b>${c}</b></td><td class="muted">${w}</td>${['o','v'].map(k=>`<td>${[1,2,3,4,5].map(n=>`<button class="b" data-k="${k}" data-i="${i}" data-n="${n}" style="padding:3px 8px;${S[k][i]===n?'background:var(--accent);color:#fff;border-color:var(--accent)':''}">${n}</button>`).join(' ')}</td>`).join('')}</tr>`).join('');
  t.querySelectorAll('button').forEach(b=>b.onclick=()=>{S[b.dataset.k][+b.dataset.i]=+b.dataset.n;r();});
  const so=S.o.reduce((a,b)=>a+b,0),sv=S.v.reduce((a,b)=>a+b,0),reg=PDE.filter((_,i)=>S.v[i]<S.o[i]).map(x=>x[0]);
  document.getElementById('pdverdict').innerHTML=`<b>Original ${so}/25 · Revised ${sv}/25.</b> ${reg.length?`<span style="color:var(--pink)">Regression in ${reg.join(', ')}: don't keep the revision until that's fixed.</span>`:sv>so?'<span style="color:var(--green)">Keep the revision.</span> Re-test if inputs change.':'No improvement, so try a different single fix.'} <span class="muted" style="font-size:13px">A practical method, not a statistically rigorous one.</span>`;}r();
 document.getElementById('pdcheck').innerHTML=PDC.map(q=>`<label class="toggle" style="padding:5px 0;border:0"><input type="checkbox"><span style="font-size:14px">${q}</span></label>`).join('');})();}


function copyBtn(btn,getText,label){btn.onclick=async()=>{try{await navigator.clipboard.writeText(getText());btn.textContent='Copied ✓';}catch(e){btn.textContent='Select the text';}setTimeout(()=>btn.textContent=label,2000);};}
