 const rel={'7-6':2.6,'7-3':2.2,'3-2':1.8,'3-0':1.2,'6-5':1.4,'8-0':1.6,'8-7':1.9,'1-0':1.3,'4-3':1.5,'5-4':1.1,'2-1':1.0};
 function W(){const m=mk.checked;return T.map((_,i)=>{const s=T.map((_,j)=>(m&&j>i)?-Infinity:(rel[i+'-'+j]||0)+(j===i?0.9:0)-Math.abs(i-j)*0.08+(!m&&j>i?0.2:0));const mx=Math.max(...s);const e=s.map(v=>v===-Infinity?0:Math.exp(v-mx));const z=e.reduce((a,b)=>a+b,0);return e.map(v=>v/z);});}
 function r(){const w=W(),m=mk.checked;
  g.innerHTML=`<table style="border-collapse:separate;border-spacing:2px;font-size:12px"><tr><td></td>${T.map(t=>`<td class="mono" style="writing-mode:vertical-rl;transform:rotate(180deg);padding:2px;color:var(--muted)">${t}</td>`).join('')}</tr>${w.map((row,i)=>`<tr data-r="${i}" style="cursor:pointer"><td class="mono" style="padding:2px 6px;text-align:right;${i===sel?'color:var(--accent);font-weight:700':''}">${T[i]}</td>${row.map((v,j)=>`<td title="${T[i]} → ${T[j]}: ${(v*100).toFixed(0)}%" style="width:30px;height:26px;border-radius:4px;${m&&j>i?'background:repeating-linear-gradient(45deg,var(--soft),var(--soft) 3px,transparent 3px,transparent 6px)':`background:color-mix(in srgb,var(--orange) ${Math.round(v*100)}%,var(--panel))`};${i===sel?'outline:2px solid var(--accent)':''}"></td>`).join('')}</tr>`).join('')}</table>`;
  g.querySelectorAll('tr[data-r]').forEach(tr=>tr.onclick=()=>{sel=+tr.dataset.r;r();});
  const row=w[sel].map((v,j)=>[T[j],v]).filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]).slice(0,5);
  info.innerHTML=`<h3 style="margin-top:0">"${T[sel]}" attends to…</h3>${row.map(([t,v])=>`<div class="memrow" style="grid-template-columns:90px 1fr 46px"><span class="mono">${t}</span><div class="membar" style="width:${v*100}%;background:var(--orange)"></div><b class="mono">${(v*100).toFixed(0)}%</b></div>`).join('')}<p class="muted" style="font-size:13px;margin:8px 0 0">${m?`With the causal mask, "${T[sel]}" can only see itself and earlier tokens (hatched cells are masked to −∞ before softmax).`:'Without the mask, every token sees the whole sentence. That is what encoders like BERT do. A decoder can\'t, because the future tokens don\'t exist yet when it generates.'}</p>`;}
