  box.querySelectorAll('input').forEach(x=>x.onchange=()=>{x.checked?on.add(+x.dataset.i):on.delete(+x.dataset.i);r();});
  const pats=[...new Set([...on].map(i=>LWQ[i][1]))].sort();
  document.getElementById('lwrec').textContent=pats.length?'→ '+pats.map(p=>LW[p].t).join(' + '):'→ A single, well-prompted LLM call may be enough. Start there.';
