/* SOP builder */
if(document.getElementById("sop-workflow")){(function(){const f=document.getElementById('sopform'),o=document.getElementById('sopout'),rd=document.getElementById('sopready');
 f.innerHTML=SOP.map(([t,c,tip,k,v],i)=>`<label style="display:block;margin-bottom:12px"><b style="font-size:13.5px">${i+1} · ${t}</b> <span class="muted" style="font-size:12px">${c}</span><textarea data-k="${k}" rows="${v.includes('\n')?4:2}" style="display:block;width:100%;margin-top:4px;font:13px/1.4 'JetBrains Mono',monospace;padding:8px;border-radius:8px;border:1px solid var(--line);background:var(--bg);color:var(--ink);resize:vertical">${esc(v)}</textarea></label>`).join('');
 const lines=v=>v.split('\n').map(x=>x.trim()).filter(Boolean);
 function r(){const V={};f.querySelectorAll('textarea').forEach(t=>V[t.dataset.k]=t.value.trim());
  o.textContent=`workflow: ${(V.process.split(':')[0]||'unnamed').trim()}\ndescription: ${V.process}\ntrigger: ${V.trigger}\ninputs:\n${lines(V.inputs.replace(/;/g,'\n')).map(x=>'  - '+x).join('\n')}\nsteps:\n${lines(V.steps).map((x,i)=>`  ${i+1}. ${x}`).join('\n')}\ndecisions:\n${lines(V.decisions).map(x=>'  - '+x).join('\n')}\nexceptions:  # route to a human, don't force through\n${lines(V.exceptions.replace(/;/g,'\n')).map(x=>'  - '+x).join('\n')}\ntools:  # least privilege\n${lines(V.tools).map(x=>'  - '+x).join('\n')}\nhuman_review: ${V.review}\ntesting: ${V.test}`;
  const checks=[['A trigger is defined',!!V.trigger],['At least 3 steps are mapped',lines(V.steps).length>=3],['Every branch has a rule',lines(V.decisions).length>=2],['Exceptions are listed',!!V.exceptions],['Write tools are scoped',!/write/i.test(V.tools)||/draft|approve|review/i.test(V.tools+V.review)],['Human review comes before consequences',/approv|review/i.test(V.review)],['A test plan with sample data exists',/\d/.test(V.test)]];
  const ok=checks.filter(c=>c[1]).length,col=ok===checks.length?'green':ok>=5?'amber':'pink';
  rd.innerHTML=`<div class="ctlrow" style="margin-top:0"><h3 style="margin:0">Readiness</h3><b style="margin-left:auto;font-size:22px;color:var(--${col})">${ok}/${checks.length}</b></div>`+checks.map(([t,c])=>`<div style="padding:4px 0;font-size:14px">${c?'<span style="color:var(--green)">✓</span>':'<span style="color:var(--pink)">✗</span>'} ${t}</div>`).join('')+`<p class="muted" style="margin:8px 0 0;font-size:13px">${ok===checks.length?'Ready to pilot on sample data.':'Fix the ✗ items before you automate.'}</p>`;}
 f.querySelectorAll('textarea').forEach(t=>t.oninput=r);r();
 document.getElementById('sopcopy').onclick=async e=>{try{await navigator.clipboard.writeText(o.textContent);e.target.textContent='Copied ✓';}catch(err){e.target.textContent='Select the text';}setTimeout(()=>e.target.textContent='Copy spec',2000);};})();}

