/* cosine similarity */
if(document.getElementById("rag")){(function(){const S=300,O=150,K=115;let V={q:[.85,.45],d:[.55,.75]};const box=document.getElementById('cosbox');
 function draw(){const [qx,qy]=V.q,[dx,dy]=V.d,dot=qx*dx+qy*dy,nq=Math.hypot(qx,qy),nd=Math.hypot(dx,dy),c=dot/(nq*nd||1),ang=Math.acos(Math.max(-1,Math.min(1,c)))*180/Math.PI;
  const P=([x,y])=>[O+x*K,O-y*K];const [qX,qY]=P(V.q),[dX,dY]=P(V.d);
  box.innerHTML=`<svg viewBox="0 0 ${S} ${S}" style="width:100%;max-width:340px;display:block;margin:auto;touch-action:none" id="cossvg">
   <defs><marker id="cma" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0,0L10,5L0,10z" fill="var(--blue)"/></marker><marker id="cmb" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0,0L10,5L0,10z" fill="var(--orange)"/></marker></defs>
   <circle cx="${O}" cy="${O}" r="${K}" fill="none" stroke="var(--line)" stroke-dasharray="3 5"/><line x1="10" y1="${O}" x2="${S-10}" y2="${O}" stroke="var(--line)"/><line x1="${O}" y1="10" x2="${O}" y2="${S-10}" stroke="var(--line)"/>
   <line x1="${O}" y1="${O}" x2="${qX}" y2="${qY}" stroke="var(--blue)" stroke-width="3" marker-end="url(#cma)"/><line x1="${O}" y1="${O}" x2="${dX}" y2="${dY}" stroke="var(--orange)" stroke-width="3" marker-end="url(#cmb)"/>
   <circle data-v="q" cx="${qX}" cy="${qY}" r="11" fill="var(--blue)" fill-opacity=".25" stroke="var(--blue)" style="cursor:grab"/><text x="${qX+12}" y="${qY-10}" style="font:700 13px Inter;fill:var(--blue)">q</text>
   <circle data-v="d" cx="${dX}" cy="${dY}" r="11" fill="var(--orange)" fill-opacity=".25" stroke="var(--orange)" style="cursor:grab"/><text x="${dX+12}" y="${dY-10}" style="font:700 13px Inter;fill:var(--orange)">d</text></svg>`;
  const verdict=c>.8?['green','very similar']:c>.4?['amber','somewhat related']:c>-.2?['gray','unrelated']:['pink','opposite'];
  document.getElementById('cosout').innerHTML=`q = [${qx.toFixed(2)}, ${qy.toFixed(2)}] &nbsp; d = [${dx.toFixed(2)}, ${dy.toFixed(2)}]<br>q·d = ${dot.toFixed(3)} &nbsp; ‖q‖ = ${nq.toFixed(3)} &nbsp; ‖d‖ = ${nd.toFixed(3)}<br><b style="font-size:18px;color:var(--${verdict[0]})">cos(q,d) = ${c.toFixed(3)}</b> &nbsp;<span class="muted">angle ${ang.toFixed(0)}° · ${verdict[1]}</span>`;
  const svg=box.querySelector('svg');let drag=null;
  svg.querySelectorAll('circle[data-v]').forEach(h=>h.addEventListener('pointerdown',e=>{drag=h.dataset.v;svg.setPointerCapture(e.pointerId);e.preventDefault();}));
  svg.addEventListener('pointermove',e=>{if(!drag)return;const r=svg.getBoundingClientRect(),x=((e.clientX-r.left)/r.width*S-O)/K,y=-((e.clientY-r.top)/r.height*S-O)/K;
   const n=Math.hypot(x,y),m=Math.min(1.2,Math.max(.15,n));V[drag]=[x/n*m,y/n*m];const keep=drag;draw();drag=keep;});
  svg.addEventListener('pointerup',()=>drag=null);}
 draw();})();}

/* chunking */
function chunk(){const N=+ckn.value,sz=+cks.value,ov=Math.min(+cko.value,sz-50);cknv.textContent=N.toLocaleString();cksv.textContent=sz;ckov.textContent=ov;
 const n=Math.max(1,Math.ceil((N-ov)/(sz-ov))),stored=n*sz,dup=Math.max(0,stored-N);
 const show=Math.min(n,24);let bar='';for(let i=0;i<show;i++)bar+=`<div style="flex:1;min-width:6px;height:22px;border-radius:4px;background:color-mix(in srgb,var(--blue) ${i%2?55:80}%,transparent);margin-right:${ov?-Math.round(ov/sz*8):2}px"></div>`;
 ckout.innerHTML=`<div style="display:flex;margin:10px 0 12px">${bar}${n>show?`<span class="muted mono" style="margin-left:8px;font-size:12px">+${n-show} more</span>`:''}</div><div class="stats"><div class="stat"><b>${n.toLocaleString()}</b><span>chunks → vectors to store</span></div><div class="stat"><b>${stored.toLocaleString()}</b><span>tokens embedded</span></div><div class="stat"><b>${Math.round(dup/N*100)}%</b><span>extra from overlap</span></div></div>`;}
const ckn=document.getElementById('ckn'),cks=document.getElementById('cks'),cko=document.getElementById('cko'),cknv=document.getElementById('cknv'),cksv=document.getElementById('cksv'),ckov=document.getElementById('ckov'),ckout=document.getElementById('ckout');
if(document.getElementById("rag")){[ckn,cks,cko].forEach(x=>x.oninput=chunk);}if(document.getElementById("rag")){chunk();}

/* top-k + rerank */
function topk(){const k=+document.getElementById('tkk').value,rr=document.getElementById('tkr').checked;document.getElementById('tkkv').textContent=k;
 const bySim=TK.map((c,i)=>({...c,i,sim:c[2],r:c[3]})).sort((a,b)=>b.sim-a.sim),top=bySim.slice(0,k),fin=rr?[...top].sort((a,b)=>b.r-a.r):top;
 document.getElementById('tktable').innerHTML='<tr><th>Final rank</th><th>Chunk</th><th>Initial score sim(q,d)</th><th>Rerank score s′</th><th></th></tr>'+fin.map((c,j)=>{const was=top.indexOf(c);const mv=rr?(was>j?`<span style="color:var(--green)">▲ ${was-j}</span>`:was<j?`<span style="color:var(--pink)">▼ ${j-was}</span>`:'—'):'';return `<tr><td><b>${j+1}</b></td><td><b>${c[0]}</b> <span class="muted">${c[1]}</span></td><td class="mono">${c.sim.toFixed(2)}</td><td class="mono">${rr?c.r.toFixed(2):'—'}</td><td>${mv}</td></tr>`;}).join('')+
  bySim.slice(k).map(c=>`<tr style="opacity:.4"><td>–</td><td>${c[0]} <span class="muted">${c[1]}</span></td><td class="mono">${c.sim.toFixed(2)}</td><td colspan="2" class="muted">not in top-${k}</td></tr>`).join('');
 document.getElementById('ctxpre').textContent='Use the context below to answer the question.\nCite chunk IDs.\n\nContext:\n'+fin.map(c=>`[${c[0]}] ${c[1]}`).join('\n')+'\n\nQuestion: How do we handle a P1 payments outage?';}
if(document.getElementById("rag")){document.getElementById('tkk').oninput=topk;}if(document.getElementById("rag")){document.getElementById('tkr').onchange=topk;}if(document.getElementById("rag")){topk();}

/* eval metrics */
const EVL=[1,0,1,0,0,1,0,0];const EV_OUT=2;
function evals(){const k=+document.getElementById('evk').value;document.getElementById('evkv').textContent=k;const tot=EVL.reduce((a,b)=>a+b,0)+EV_OUT;document.getElementById('evtot').textContent=tot;
 document.getElementById('evlist').innerHTML=EVL.map((r,i)=>`<button class="tab ${r?'on':''}" data-i="${i}" style="${i>=k?'opacity:.4':''}">#${i+1} ${r?'✓ relevant':'✗'}</button>`).join('');
 document.querySelectorAll('#evlist button').forEach(b=>b.onclick=()=>{EVL[+b.dataset.i]^=1;evals();});
 const hit=EVL.slice(0,k).reduce((a,b)=>a+b,0),fr=EVL.findIndex(x=>x);
 document.getElementById('evstats').innerHTML=`<div class="stat"><b>${(hit/tot).toFixed(2)}</b><span>Recall@${k} = ${hit}/${tot}</span></div><div class="stat"><b>${(hit/k).toFixed(2)}</b><span>Precision@${k} = ${hit}/${k}</span></div><div class="stat"><b>${fr<0?'0.00':(1/(fr+1)).toFixed(2)}</b><span>MRR (first relevant at #${fr<0?'–':fr+1})</span></div>`;}
if(document.getElementById("rag")){document.getElementById('evk').oninput=evals;}if(document.getElementById("rag")){evals();}

/* agent repo tree */
if(document.getElementById("agent-kit")){(function(){const tree=document.getElementById('repotree'),info=document.getElementById('repoinfo'),fl=document.getElementById('repof');let filt='all';
 const BADGE={core:['core','blue'],new:['★ new','amber'],open:['open std','green']};
 const pname=h=>{const a=document.querySelector(`#nav a[data-href="#${h}"]`);return a?(a.dataset.label||a.textContent).trim():h;};
 function sel(fi,i){const [folder,,c,files]=REPO[fi],[n,b,d,lnk]=files[i],[bl,bc]=BADGE[b];
  tree.querySelectorAll('.rf').forEach(x=>x.classList.toggle('sel',x.dataset.k===fi+'-'+i));
  info.innerHTML=`<span class="pill" style="color:var(--${c})">${folder==='Root'?'my-ai-agent/':'my-ai-agent/'+folder}</span><h3 style="margin:8px 0 4px;font-family:'JetBrains Mono',monospace">${n}</h3><span class="pill" style="color:var(--${bc})">${bl}</span><p style="margin:10px 0 0">${d}</p>${lnk?`<p style="margin:10px 0 0"><a href="#${lnk}">Related: ${pname(lnk)} →</a></p>`:''}`;}
 function render(){fl.innerHTML=[['all','All 30'],['core','core · 20'],['new','★ new · 5'],['open','open std · 5']].map(([k,l])=>`<button class="tab ${filt===k?'on':''}" data-f="${k}">${l}</button>`).join('');
  fl.querySelectorAll('button').forEach(b=>b.onclick=()=>{filt=b.dataset.f;render();});
  tree.innerHTML='<div style="font-weight:700;margin-bottom:6px">📁 my-ai-agent/ <span class="muted" style="font-weight:400">6 folders · 30 files</span></div>'+REPO.map(([f,why,c,files],fi)=>`<div style="margin:0 0 10px 6px;padding-left:12px;border-left:2px solid color-mix(in srgb,var(--${c}) 40%,transparent)"><div style="color:var(--${c});font-weight:700">${f==='Root'?'· root files':'📁 '+f} <span class="muted" style="font-weight:400;font-family:Inter">— ${why}</span></div>${files.map(([n,b],i)=>filt!=='all'&&filt!==b?'':`<div class="rf" data-k="${fi}-${i}" tabindex="0" style="display:flex;gap:8px;align-items:center;padding:3px 8px;border-radius:6px;cursor:pointer">${n.endsWith('/')?'📂':'📄'} ${n} <span class="pill" style="margin-left:auto;font-family:Inter;color:var(--${BADGE[b][1]})">${BADGE[b][0]}</span></div>`).join('')}</div>`).join('');
  tree.querySelectorAll('.rf').forEach(x=>{const [fi,i]=x.dataset.k.split('-').map(Number);x.onclick=()=>sel(fi,i);x.onkeydown=e=>{if(e.key==='Enter')sel(fi,i);};});}
 render();sel(1,0);
 document.getElementById('repocopy').onclick=async e=>{const t='my-ai-agent/\n'+REPO.map(([f,,,files],fi)=>{const last=fi===REPO.length-1;if(f==='Root')return files.map(x=>`├── ${x[0]}`.padEnd(30)+`# ${x[2]}`).join('\n');return `${last?'└──':'├──'} ${f}\n`+files.map(([n,,d],i)=>`${last?'    ':'│   '}${i===files.length-1?'└──':'├──'} ${n}`.padEnd(34)+`# ${d}`).join('\n');}).join('\n');
  try{await navigator.clipboard.writeText(t);e.target.textContent='Copied ✓';}catch(err){info.innerHTML='<pre class="code">'+esc(t)+'</pre>';e.target.textContent='Shown in panel';}setTimeout(()=>e.target.textContent='Copy tree as text',2000);};})();}


