/* ---- DEEP PAGES: interactives ---- */
(function(){
/* gradient descent playground: f(x,y)=0.5*(x^2 + 10*y^2) */
const sv=document.getElementById('gdSvg');if(sv){
 const f=(x,y)=>0.5*(x*x+10*y*y),gx=x=>x,gy=y=>10*y;const X0=-4.2,Y0=1.6;
 const px=x=>210+x*44,py=y=>150-y*70;
 let contours='';[0.5,2,5,10,18,28].forEach(c=>{const a=Math.sqrt(2*c),b=Math.sqrt(2*c/10);contours+=`<ellipse cx="210" cy="150" rx="${a*44}" ry="${b*70}" fill="none" stroke="var(--line)" stroke-width="1.2"/>`;});
 function run(){const lr=+document.getElementById('gdLr').value/100,mom=document.getElementById('gdMom').checked,n=+document.getElementById('gdN').value;
  document.getElementById('gdLrV').textContent=lr.toFixed(2);document.getElementById('gdNV').textContent=n;
  let x=X0,y=Y0,vx=0,vy=0;const pts=[[x,y]],ls=[f(x,y)];let div=false;
  for(let i=0;i<n;i++){const ax=gx(x),ay=gy(y);if(mom){vx=0.9*vx-lr*ax;vy=0.9*vy-lr*ay;x+=vx;y+=vy;}else{x-=lr*ax;y-=lr*ay;}
   if(!isFinite(x)||Math.abs(x)>60||Math.abs(y)>60){div=true;break;}pts.push([x,y]);ls.push(f(x,y));}
  const cl=(v,a,b)=>Math.max(a,Math.min(b,v));
  sv.innerHTML=contours+`<circle cx="210" cy="150" r="4" fill="var(--green)"/><polyline points="${pts.map(([a,b])=>cl(px(a),-20,440)+','+cl(py(b),-20,320)).join(' ')}" fill="none" stroke="var(--purple)" stroke-width="2"/>`+pts.map(([a,b],i)=>`<circle cx="${cl(px(a),-20,440)}" cy="${cl(py(b),-20,320)}" r="${i?2.6:5}" fill="${i?'var(--purple)':'var(--orange)'}"/>`).join('')+`<text x="10" y="18" font-size="12" fill="var(--muted)">loss contours · ● start · ● minimum</text>`;
  const mx=Math.log10(Math.max(...ls)+1e-9),mn=-4;const ly=v=>270-((Math.log10(Math.max(v,1e-4))-mn)/(Math.max(mx,mn+1)-mn))*240;const lx=i=>20+i*(270/Math.max(n,1));
  document.getElementById('gdLoss').innerHTML=`<line x1="20" y1="272" x2="292" y2="272" stroke="var(--line)"/><text x="20" y="292" font-size="11" fill="var(--muted)">step → (log loss)</text><polyline points="${ls.map((v,i)=>lx(i)+','+ly(v).toFixed(1)).join(' ')}" fill="none" stroke="var(--blue)" stroke-width="2.5"/><text x="24" y="18" font-size="12" fill="var(--blue)">loss ${div?'→ ∞':ls[ls.length-1].toExponential(1)}</text>`;
  const fin=ls[ls.length-1];let m;
  if(div||fin>ls[0])m='<b>Diverging.</b> The step is so large it overshoots the steep direction of the valley and bounces outward. Lower the learning rate (for this valley, anything above 0.20 without momentum blows up).';
  else if(fin>0.05)m=`<b>Too slow.</b> Loss fell from ${ls[0].toFixed(1)} to ${fin.toFixed(2)} in ${n} steps. Progress along the shallow direction is tiny. Raise the learning rate or turn on momentum.`;
  else m=`<b>Converged.</b> Loss ${fin.toExponential(1)} after ${pts.length-1} steps.${mom?' Momentum builds speed along the valley floor.':' Notice the zig-zag across the steep direction: momentum or Adam would smooth it.'}`;
  document.getElementById('gdMsg').innerHTML=m;}
 ['gdLr','gdN'].forEach(i=>document.getElementById(i).addEventListener('input',run));document.getElementById('gdMom').addEventListener('change',run);run();}

/* adaptation chooser */
const ad=document.getElementById('adChk');if(ad){
 const Q=[['facts','The model needs facts it wasn\'t trained on, or facts that change',{rag:3}],['cite','Answers must cite sources or respect per-document permissions',{rag:2}],['live','It needs live data or must take actions (book, update, send)',{tools:3}],['format','Output must follow a strict format or house style',{fs:2,ft:1}],['narrow','It\'s a narrow, repetitive task (classify, extract) at high volume',{ft:2,ds:2}],['cost','Cost or latency at current volume is the main problem',{ds:3,ft:1}],['data','You have thousands of high-quality labeled examples',{ft:2,ds:1}],['fast','You need something working this week',{fs:2}]];
 const N={fs:['Prompting + few-shot examples','Start here: a clear system prompt with 2–5 diverse examples. Cheapest and fastest to change.'],rag:['RAG','Index your documents and retrieve per question. Knowledge stays fresh, answers can cite sources and respect permissions.'],tools:['Tools / agent','Give the model functions or MCP servers for live data and actions, with approvals for risky steps.'],ft:['Fine-tuning (LoRA)','Train adapters on your examples for consistent format, style or a narrow skill. Re-run evals on every base-model update.'],ds:['Distill into a smaller model','Use a frontier model to label data, then train a small model for the high-volume path. Keep the big model for hard cases.']};
 ad.innerHTML=Q.map(([k,l])=>`<label class="sec-item"><input type="checkbox" data-k="${k}"> ${l}</label>`).join('');
 const r=()=>{const s={fs:1,rag:0,tools:0,ft:0,ds:0};ad.querySelectorAll('input:checked').forEach(x=>{const w=Q.find(q=>q[0]===x.dataset.k)[2];for(const k in w)s[k]+=w[k];});
  const rank=Object.entries(s).filter(e=>e[1]>0).sort((a,b)=>b[1]-a[1]);const any=ad.querySelectorAll('input:checked').length;
  document.getElementById('adOut').innerHTML=!any?'<p class="muted">Tick at least one statement. With nothing special, a well-written prompt is the answer.</p>':`<b>Recommended, in order:</b><ol class="ad-ol">${rank.slice(0,3).map(([k,v])=>`<li><b>${N[k][0]}</b> <span class="pill">score ${v}</span><br><span class="muted" style="font-size:13px">${N[k][1]}</span></li>`).join('')}</ol><p class="muted" style="font-size:13px;margin:6px 0 0">These combine: RAG + tools + a good prompt is the most common production stack. Fine-tune or distill only after evals show prompting can't reach the bar.</p>`;};
 ad.addEventListener('change',r);r();}

/* context budget builder */
const cb=document.getElementById('cbSl');if(cb){
 const P=[['System prompt','sys',1500,'var(--blue)'],['Tool definitions','tl',3000,'var(--green)'],['Memory','mem',800,'var(--teal)'],['Retrieved docs','ret',8000,'var(--purple)'],['History','his',6000,'var(--orange)'],['Reserved for output','out',2000,'var(--pink)']];
 const W=[['32k',32000],['128k',128000],['200k',200000],['1M',1000000]];let win=128000;
 cb.innerHTML=P.map(([l,k,v,c])=>`<label><span style="display:inline-flex;align-items:center;gap:6px"><i style="width:9px;height:9px;border-radius:50%;background:${c};display:inline-block"></i>${l}</span><input type="range" min="0" max="40000" step="250" value="${v}" data-k="${k}"><span class="out" data-o="${k}"></span></label>`).join('')+`<label>Window<select id="cbWin">${W.map(([l,v])=>`<option value="${v}" ${v===win?'selected':''}>${l}</option>`).join('')}</select></label><label>$ / 1M input<input type="number" id="cbP" value="3" step="0.5" style="width:70px"></label><label>Cached prefix<input type="checkbox" id="cbC" checked></label>`;
 const run=()=>{win=+document.getElementById('cbWin').value;const v={};cb.querySelectorAll('input[type=range]').forEach(x=>{v[x.dataset.k]=+x.value;cb.querySelector(`[data-o="${x.dataset.k}"]`).textContent=(+x.value).toLocaleString();});
  const tot=Object.values(v).reduce((a,b)=>a+b,0),inp=tot-v.out,p=+document.getElementById('cbP').value||0,cache=document.getElementById('cbC').checked;
  const pre=v.sys+v.tl,cost=cache?((inp-pre)+pre*0.1)*p/1e6:inp*p/1e6;
  document.getElementById('cbBar').innerHTML=P.map(([l,k,,c])=>`<span title="${l}: ${v[k].toLocaleString()}" style="width:${Math.min(100,100*v[k]/win)}%;background:${c}"></span>`).join('');
  const pct=100*tot/win;document.getElementById('cbOut').innerHTML=`<b style="color:${pct>100?'var(--pink)':'var(--ink)'}">${tot.toLocaleString()} of ${win.toLocaleString()} tokens (${pct.toFixed(1)}%)${pct>100?' — over the window!':''}</b> · input cost ≈ $${cost.toFixed(4)} per call${cache?` (stable prefix of ${pre.toLocaleString()} tokens billed at ~10% when cached, illustrative)`:''} · tools + history are ${Math.round(100*(v.tl+v.his)/Math.max(tot,1))}% of the context.`;};
 cb.addEventListener('input',run);cb.addEventListener('change',run);run();}
})();

