const evr=()=>{on=[...ev.querySelectorAll('input:checked')].map(x=>+x.dataset.i);try{localStorage.setItem(K,JSON.stringify(on));}catch(e){}const p=Math.round(100*on.length/EV.length);
 document.getElementById('cmpEvOut').innerHTML=`<div style="display:flex;align-items:center;gap:12px"><b>${p}% audit-ready</b><div class="ac-bar" style="flex:1;max-width:320px"><span style="width:${p}%;background:${p>=80?'var(--green)':p>=50?'var(--amber)':'var(--pink)'}"></span></div></div><p class="muted" style="margin:6px 0 0;font-size:13px">${p>=80?'Strong. Focus on keeping evidence current.':p>=50?'Partial. Close the gaps for your highest-risk systems first.':'Early. Start with the inventory and risk classification: everything else depends on them.'}</p>`;};
