 attn:['Vaswani et al., Attention Is All You Need (2017)','https://arxiv.org/abs/1706.03762'],dlb:['Goodfellow, Bengio & Courville, Deep Learning (book)','https://www.deeplearningbook.org/'],mlcc:['Google, Machine Learning Crash Course','https://developers.google.com/machine-learning/crash-course'],
 aiidx:['Stanford HAI, AI Index Report','https://hai.stanford.edu/ai-index'],chin:['Hoffmann et al., Training Compute-Optimal LLMs (2022)','https://arxiv.org/abs/2203.15556'],igpt:['Ouyang et al., InstructGPT / RLHF (2022)','https://arxiv.org/abs/2203.02155'],lora:['Hu et al., LoRA (2021)','https://arxiv.org/abs/2106.09685'],dpo:['Rafailov et al., Direct Preference Optimization (2023)','https://arxiv.org/abs/2305.18290'],
