 'mcp':['mcp','otel'],'mcp-protocol':['mcp','rfc8693'],'mcp-clients':['mcp'],'mcp-roles':['mcp'],'a2a':['a2a','mcp'],'agent-swarms':['maf','oas','lg','bea'],'workflows':['bea','react','refl'],'build-agent':['bea','oas','maf','csup'],'agent-kit':['cc','bea'],'prompt-skills':['csup','pe'],
 'llm-judge':['judge','ragas'],'evalhub':['judge','ragas'],'llmops':['otel','sre','judge'],'cost':['finops','vllm'],'ai-security':['owasp','gai'],'guardrails':['owasp','gai','rmf'],'ai-compliance':['euai','rmf','iso','gai'],'responsible-ai':['oecd','rmf','euai'],'gov-maturity':['rmf','iso'],
