const grpOf=id=>{const a=document.querySelector(`#nav a[data-href="#${id}"]`);const g=a&&a.closest('.grp');const n=g&&g.querySelector('.gname');return n?n.textContent.trim():ATLAS.group(id);};
const fmt=d=>{try{return new Date(d+'T12:00:00').toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'});}catch(e){return d;}};
setTimeout(()=>{document.querySelectorAll('main>section').forEach(sec=>{const id=sec.id;if(['course','paths','changes','glossary'].includes(id)||sec.querySelector('.src-box'))return;
 const keys=[...new Set((PG[id]||GRP[grpOf(id)]||['aiidx']))].slice(0,6);const rv=typeof REVIEW!=='undefined'?REVIEW[id]:null;
 const box=document.createElement('details');box.className='src-box';
 box.innerHTML=`<summary><b>Sources &amp; review</b><span class="muted">${rv?`Time-sensitive · last reviewed ${fmt(rv[0])}`:'Concept page · included in the monthly review'}</span></summary><div class="src-in">${keys.length?`<p class="muted" style="margin:0 0 6px">Primary references for the ideas on this page. Figures in calculators come from your own inputs.</p><ul>${keys.map(k=>R[k]?`<li><a href="${R[k][1]}" target="_blank" rel="noopener">${H(R[k][0])}</a></li>`:'').join('')}</ul>`:''}${rv?`<p class="muted" style="margin:6px 0 0">Rechecked: ${H(rv[1])}.</p>`:''}<p class="muted" style="margin:6px 0 0">Found something out of date? Add a note below or see <a href="#about">how the Atlas stays current</a>.</p></div>`;
 const pt=sec.querySelector(':scope>.ptools');pt?sec.insertBefore(box,pt):sec.appendChild(box);});},0);

/* ===== CX metrics calculator ===== */
(function(){if(!$('cxmIn'))return;const F=[['vol','Contacts per month',100000,1000],['shareSS','Share entering self-service (%)',60,1],['cont','Resolved containment (%)',35,1],['cLive','Cost per live contact ($)',6,0.5],['cAuto','Cost per automated contact ($)',0.6,0.1],['aht','AHT today (minutes)',7,0.5],['ahtRed','AHT reduction from assist (%)',10,1],['paid','Paid hours per agent per month',160,1],['occ','Occupancy (%)',80,1],['shr','Shrinkage (%)',30,1]];
 const S=Object.assign(Object.fromEntries(F.map(f=>[f[0],f[2]])),ld('atlas-cxm-v1',{}));
 $('cxmIn').innerHTML=F.map(([k,l,,st])=>`<label>${l}<input type="number" data-k="${k}" value="${S[k]}" step="${st}" min="0"></label>`).join('');
 const run=()=>{$('cxmIn').querySelectorAll('[data-k]').forEach(x=>S[x.dataset.k]=+x.value||0);sv('atlas-cxm-v1',S);
  const ss=S.vol*S.shareSS/100,res=ss*S.cont/100,live=S.vol-res,ahtN=S.aht*(1-S.ahtRed/100);
  const save=res*(S.cLive-S.cAuto);const hrsBefore=S.vol*S.aht/60,hrsAfter=live*ahtN/60;const fte=h=>h/(S.paid*(S.occ/100)*(1-S.shr/100)||1);
  const st=(v,l,c)=>`<div class="ac-stat" style="--c:var(--${c})"><b>${v}</b><span>${l}</span></div>`;
  $('cxmOut').innerHTML=st(Math.round(res).toLocaleString(),'contacts resolved by AI / month','teal')+st(Math.round(live).toLocaleString(),'contacts still reaching people','orange')+st('$'+Math.round(save*12).toLocaleString(),'yearly cost difference on resolved contacts','green')+st((fte(hrsBefore)-fte(hrsAfter)).toFixed(1),'agent FTE of workload removed','purple');
  $('cxmNote').innerHTML=`Workload drops from <b>${Math.round(hrsBefore).toLocaleString()}</b> to <b>${Math.round(hrsAfter).toLocaleString()}</b> handled hours a month. This is a gross figure: subtract platform, implementation, knowledge upkeep and QA costs (use the <a href="#usecase-roi">ROI tools</a>), and expect containment to ramp up over months. If repeat contacts rise, your resolved containment is lower than you entered.`;};
 $('cxmIn').addEventListener('input',run);run();})();

/* ===== handoff simulator ===== */
(function(){if(!$('hoSim'))return;const T=[['ask','Customer asked for a person',100,'Always honor it, immediately.'],['risk','High-risk topic (complaint, legal, vulnerability, bereavement, fraud)',100,'Policy: route to a trained person.'],['fail','Virtual agent failed twice on the same step',70,'Repeated failure is the strongest predictor of a bad experience.'],['neg','Sentiment is negative and getting worse',50,'Combine with other signals.'],['conf','Low confidence in understanding the request',40,'Ask one clarifying question first.'],['auth','Needs an action the virtual agent isn\'t permitted to do',100,'Hand off with the action pre-filled.'],['vip','High-value or at-risk customer',30,'Prioritize in the queue rather than forcing handoff.'],['long','Conversation over 10 turns',30,'Long loops usually mean the bot is stuck.']];
 let on=new Set();const draw=()=>{const sc=Math.min(100,[...on].reduce((a,k)=>a+T.find(t=>t[0]===k)[2],0));const v=sc>=100?['Hand off now','pink','A hard rule fired.']:sc>=70?['Offer a person','amber','Offer the customer a person and keep helping while they decide.']:sc>=40?['Clarify, then decide','blue','Ask a clarifying question or confirm the goal, then re-check.']:['Continue','green','Keep going with the virtual agent; the customer can still ask for a person at any time.'];
  $('hoSim').innerHTML=`<div class="ho-l">${T.map(t=>`<label class="ck2"><input type="checkbox" data-k="${t[0]}"${on.has(t[0])?' checked':''}> <span>${t[1]}<br><span class="muted" style="font-size:12.5px">${t[3]}</span></span></label>`).join('')}</div><div class="callout" style="margin:12px 0 0;--accent:var(--${v[1]})"><b style="color:var(--${v[1]})">${v[0]}</b> · handoff score ${sc}/100<br>${v[2]}</div>`;};
 $('hoSim').addEventListener('change',e=>{const k=e.target.dataset.k;if(!k)return;e.target.checked?on.add(k):on.delete(k);draw();});draw();})();

/* ===== migration scorer ===== */
(function(){if(!$('miScore'))return;const F=[['vol','Volume','Rare','Top-10 intent'],['var','How varied are the requests?','Always the same steps','Every case differs'],['data','Data the bot needs','None or public','Many systems'],['risk','Risk if wrong','Low','Money, legal or safety']];const S={vol:3,var:3,data:2,risk:2,name:'Order status'};
 const draw=()=>{const fixed=S.var<=2&&S.risk>=3,human=S.risk>=5||(S.risk>=4&&S.var>=4),llm=!human&&S.var>=3;
  const v=human?['Route to a person (AI assists)','pink','High risk with high variation: let a trained person own it, with agent assist and a summary.']:fixed||(!llm)?['Keep a fixed flow','navy','Predictable steps or strict rules: a deterministic flow is cheaper, faster and easier to audit. Use an LLM only to understand the request.']:['LLM agent with guardrails','purple','Varied requests where explanation helps: ground it in approved knowledge, give it scoped tools and keep fixed flows for authentication and payments.'];
  const pri=S.vol>=4?'Do it early: it carries real volume.':S.vol<=2?'Low volume: do it later, or leave it as is.':'Medium priority.';
  $('miScore').innerHTML=`<div class="ctlrow"><label>Intent <input id="miName" value="${H(S.name)}"></label></div><div class="grid g2" style="margin-top:8px">${F.map(([k,l,a,b])=>`<label class="mi-f"><span><b>${l}</b><span class="muted">${S[k]}/5</span></span><input type="range" min="1" max="5" value="${S[k]}" data-k="${k}"><span class="mi-ends muted"><span>${a}</span><span>${b}</span></span></label>`).join('')}</div><div class="callout" style="margin:12px 0 0;--accent:var(--${v[1]})"><b style="color:var(--${v[1]})">${H(S.name)}: ${v[0]}</b><br>${v[2]} ${pri}</div>`;
  $('miName').oninput=e=>{S.name=e.target.value;$('miScore').querySelector('.callout b').textContent=S.name+': '+v[0];};};
 $('miScore').addEventListener('input',e=>{const k=e.target.dataset.k;if(k){S[k]=+e.target.value;draw();}});draw();})();

/* ===== QA rubric builder ===== */
(function(){if(!$('qaRub'))return;const C=[['greet','Greeting & identification','Correct greeting; identity verified before account details',10,1],['und','Understood the issue','Restated or confirmed the customer\'s goal',15,0],['acc','Accurate answer','Information matches policy and the customer\'s records',25,1],['res','Resolution','Issue resolved, or a clear next step and timeline',20,0],['comp','Compliance','Required disclosures made; no prohibited statements',15,1],['emp','Empathy & tone','Acknowledged feelings; professional, plain language',10,0],['eff','Efficiency','No unnecessary holds, transfers or repetition',5,0],['pii','Data handling','Didn\'t read out or request unnecessary personal data',10,1]];
 const S=ld('atlas-qa-v1',null)||Object.fromEntries(C.map(c=>[c[0],{on:true,w:c[3],fatal:!!c[4]}]));
 const draw=()=>{const tot=C.reduce((a,c)=>a+(S[c[0]].on?S[c[0]].w:0),0);
  $('qaRub').innerHTML=`<div class="tablewrap"><table><tr><th></th><th>Criterion</th><th>Weight</th><th>Auto-fail</th></tr>${C.map(c=>{const s=S[c[0]];return `<tr><td><input type="checkbox" data-k="${c[0]}" data-f="on"${s.on?' checked':''}></td><td><b>${c[1]}</b><br><span class="muted" style="font-size:12.5px">${c[2]}</span></td><td><input type="number" min="0" max="100" value="${s.w}" data-k="${c[0]}" data-f="w" style="width:64px"></td><td><input type="checkbox" data-k="${c[0]}" data-f="fatal"${s.fatal?' checked':''}></td></tr>`;}).join('')}</table></div><div class="ctlrow" style="margin-top:10px"><span class="muted">Total weight <b style="color:${tot===100?'var(--green)':'var(--amber)'}">${tot}</b>${tot===100?'':' (aim for 100)'}</span><button class="b pri" id="qaExp">⤓ Judge prompt</button><span class="muted" id="qaMsg"></span></div>`;
  $('qaExp').onclick=()=>{const act=C.filter(c=>S[c[0]].on);const p=`You are a contact-center QA analyst. Score the conversation transcript below against this rubric.\n\n${act.map((c,i)=>`${i+1}. ${c[1]} (weight ${S[c[0]].w}${S[c[0]].fatal?', AUTO-FAIL if not met':''}): ${c[2]}`).join('\n')}\n\nFor each criterion return: met (yes/no/partial), score 0-${'{weight}'}, and a short quote from the transcript as evidence. If any AUTO-FAIL criterion is not met, the overall result is FAIL regardless of score. Return JSON: {"criteria":[{"name","met","score","evidence"}],"total":0-100,"result":"PASS|FAIL","coaching_tip":"one sentence"}.\n\nTRANSCRIPT:\n{{transcript}}`;saveFile('qa-judge-prompt.txt',p,$('qaMsg'));};};
 $('qaRub').addEventListener('change',e=>{const k=e.target.dataset.k,f=e.target.dataset.f;if(!k)return;S[k][f]=f==='w'?(+e.target.value||0):e.target.checked;sv('atlas-qa-v1',S);draw();});draw();})();

/* ===== discovery kit ===== */
(function(){if(!$('dkQ'))return;const QB=[['Business & outcomes','green',['What problem are we solving, and for whom?','How is it measured today, and what is the baseline?','What does success look like in 90 days? In a year?','Who is the executive sponsor, and what do they need to see?','What is the cost of doing nothing?']],
  ['Users & process','blue',['Who are the users, how many, and in which channels and languages?','Walk me through the process today, step by step. Where does it break?','Which steps need human judgment or approval?','What are the top requests by volume?','What happens when things go wrong today?']],
  ['Data & knowledge','purple',['Where does the knowledge live, who owns it, and how current is it?','Which systems hold the records the AI must read or update?','Is there personal, payment or health data involved?','Who can see what? How are permissions managed?','Do we have real examples (transcripts, tickets) to build a test set?']],
  ['Systems & integration','teal',['Which systems need integration, and do they have APIs?','What identity provider is used for sign-in?','Are there existing bots, IVRs or automations to replace or coexist with?','What environments exist (dev, test, prod), and how do releases work?','Any network, residency or vendor restrictions?']],
  ['Risk, security & compliance','pink',['Which regulations apply (industry, privacy, AI-specific)?','What must the AI never do or say?','Which actions are irreversible and need confirmation?','Who signs off on security and privacy reviews, and how long do they take?','What is the incident and escalation process?']],
  ['Delivery & ownership','amber',['Who owns the solution after go-live?','Who maintains knowledge and answers?','What is the budget and timeline, and what is fixed?','What are the dependencies on other teams?','How will we decide to go live (quality gate)?']]];
 const ST=[['Executive sponsor','Business value, risk, timeline','Monthly'],['Process / business owner','Outcomes, process fit, adoption','Weekly'],['Frontline users or team leads','Day-to-day reality, edge cases','Week 1, then at testing'],['IT / platform owner','Integration, environments, support','Weekly'],['Security & privacy','Data flows, access, compliance','Early review, then sign-off'],['Data / knowledge owner','Content quality, freshness, permissions','Week 1–2'],['Legal / compliance','Regulation, disclosures, contracts','As needed, early']];
 const COL=['Process maps or SOPs','Sample transcripts, tickets or emails (redacted)','Knowledge base export or links','System list with API documentation','Current metrics and baselines','Org chart for the project','Security questionnaire and policies','Brand and tone guidelines'];
 const K='atlas-dk-v1';const S=Object.assign({c:'',u:'',q:{},n:{},col:{}},ld(K,{}));
 $('dkCust').value=S.c;$('dkUse').value=S.u;
 $('dkQ').innerHTML=QB.map(([g,c,qs],gi)=>`<details class="card dk-g" style="--c:var(--${c})"${gi===0?' open':''}><summary><b>${g}</b> <span class="muted dk-n" data-g="${gi}"></span></summary>${qs.map((q,qi)=>{const k=gi+'.'+qi;return `<div class="dk-q"><label class="ck2"><input type="checkbox" data-q="${k}"${S.q[k]?' checked':''}> <span>${H(q)}</span></label><input class="dk-note" data-n="${k}" placeholder="Notes / answer" value="${H(S.n[k]||'')}"></div>`;}).join('')}</details>`).join('');
 $('dkSt').innerHTML=`<table><tr><th>Stakeholder</th><th>Cares about</th><th>When to meet</th></tr>${ST.map(r=>`<tr><td><b>${r[0]}</b></td><td class="muted">${r[1]}</td><td class="muted">${r[2]}</td></tr>`).join('')}</table>`;
 $('dkCol').innerHTML=`<div class="grid g2">${COL.map((c,i)=>`<label class="ck2"><input type="checkbox" data-c="${i}"${S.col[i]?' checked':''}> <span>${c}</span></label>`).join('')}</div>`;
 const prog=()=>{const n=QB.reduce((a,g)=>a+g[2].length,0),d=Object.values(S.q).filter(Boolean).length;$('dkProg').textContent=`${d}/${n} questions covered · ${Object.values(S.col).filter(Boolean).length}/${COL.length} documents collected`;
  document.querySelectorAll('.dk-n').forEach(el=>{const gi=+el.dataset.g;const t=QB[gi][2].length,dd=QB[gi][2].filter((_,qi)=>S.q[gi+'.'+qi]).length;el.textContent=`${dd}/${t}`;});sv(K,S);};
 document.getElementById('fde-discovery').addEventListener('input',e=>{const t=e.target;if(t.dataset.q)S.q[t.dataset.q]=t.checked;else if(t.dataset.n)S.n[t.dataset.n]=t.value;else if(t.dataset.c)S.col[t.dataset.c]=t.checked;else if(t.id==='dkCust')S.c=t.value;else if(t.id==='dkUse')S.u=t.value;prog();});
 $('dkMd').onclick=()=>{const md=`# Requirements brief: ${S.u||'AI use case'}\n**Customer:** ${S.c||'—'}  \n**Date:** ${new Date().toISOString().slice(0,10)}\n\n`+QB.map(([g,,qs],gi)=>`## ${g}\n`+qs.map((q,qi)=>{const k=gi+'.'+qi;return `- ${S.q[k]?'[x]':'[ ]'} **${q}**${S.n[k]?`\n  ${S.n[k]}`:''}`;}).join('\n')).join('\n\n')+`\n\n## Stakeholders\n`+ST.map(r=>`- **${r[0]}**: ${r[1]} (${r[2]})`).join('\n')+`\n\n## Documents\n`+COL.map((c,i)=>`- ${S.col[i]?'[x]':'[ ]'} ${c}`).join('\n')+`\n\n## Open questions\n`+QB.flatMap(([,,qs],gi)=>qs.map((q,qi)=>!S.q[gi+'.'+qi]?`- ${q}`:'')).filter(Boolean).join('\n')+'\n';saveFile(((S.c||'customer').toLowerCase().replace(/[^a-z0-9]+/g,'-'))+'-requirements.md',md,$('dkMsg'));};
 $('dkReset').onclick=()=>{{Object.assign(S,{c:'',u:'',q:{},n:{},col:{}});sv(K,S);document.querySelectorAll('#fde-discovery input').forEach(x=>{if(x.type==='checkbox')x.checked=false;else x.value='';});prog();}};prog();})();

/* ===== privacy lab ===== */
(function(){if(!$('pvLab'))return;const P=[['EMAIL',/[\w.+-]+@[\w-]+\.[\w.-]+/g],['CARD',/\b(?:\d[ -]?){13,16}\b/g],['SSN',/\b\d{3}-\d{2}-\d{4}\b/g],['PHONE',/(?:\+?\d{1,2}[ .-]?)?\(?\d{3}\)?[ .-]?\d{3}[ .-]?\d{4}\b/g],['ACCOUNT',/\b(?:acct|account)[ #:]*\d{6,12}\b/gi],['DATE',/\b\d{1,2}\/\d{1,2}\/\d{2,4}\b/g]];
 const sample='Hi, this is Maria Lopez. My account #48213977 was charged twice. Card 4111 1111 1111 1111, exp 09/28. Call me at (407) 555-0142 or maria.lopez@example.com. DOB 03/14/1986.';
 let mode='token';$('pvLab').innerHTML=`<textarea id="pvIn" rows="3" style="width:100%">${H(sample)}</textarea><div class="ctlrow" style="margin:8px 0"><div class="chips" id="pvMode" style="margin-left:0"><button class="chip on" data-m="token">Tokenize</button><button class="chip" data-m="mask">Mask</button><button class="chip" data-m="remove">Remove</button></div></div><div class="pv-out" id="pvOut"></div><div class="tablewrap" id="pvVault" style="margin-top:8px"></div><p class="muted" style="font-size:12.5px;margin:8px 0 0">Note what it misses: the name "Maria Lopez" isn't caught by patterns. That's why production redaction adds entity recognition, and why you test on real samples.</p>`;
 const run=()=>{let t=$('pvIn').value;const vault=[];const cnt={};P.forEach(([k,re])=>{t=t.replace(re,m=>{cnt[k]=(cnt[k]||0)+1;const tok=`<${k}_${cnt[k]}>`;vault.push([tok,m]);return mode==='token'?tok:mode==='mask'?m.replace(/[A-Za-z0-9]/g,'•'):'[removed]';});});
  $('pvOut').textContent=t;$('pvVault').innerHTML=mode==='token'&&vault.length?`<table><tr><th>Token (what the model sees)</th><th>Original (kept in the vault)</th></tr>${vault.map(v=>`<tr><td><code>${H(v[0])}</code></td><td class="muted">${H(v[1])}</td></tr>`).join('')}</table>`:'';};
 $('pvIn').oninput=run;$('pvMode').onclick=e=>{const b=e.target.closest('[data-m]');if(!b)return;mode=b.dataset.m;$('pvMode').querySelectorAll('.chip').forEach(c=>c.classList.toggle('on',c===b));run();};run();})();

