function wrap(t,font,max){cv.font=font;const out=[];String(t||'').split('\n').forEach(par=>{let line='';par.split(/\s+/).filter(Boolean).forEach(w=>{const tr=line?line+' '+w:w;if(cv.measureText(tr).width<=max)line=tr;else{if(line)out.push(line);if(cv.measureText(w).width>max){let p='';for(const ch of w){if(cv.measureText(p+ch).width>max){out.push(p);p=ch;}else p+=ch;}line=p;}else line=w;}});if(line)out.push(line);});return out;}
