   g+=`<rect x="${x}" y="${yy}" width="${cw}" height="${h}" rx="${T.rad}" fill="${T.card}" stroke="${S.theme==='editorial'||S.theme==='clean'?hexA(T.acc,.18):c}" stroke-width="${S.theme==='sketch'?2.2:1.5}"${T.dash&&S.theme==='sketch'?` stroke-dasharray="${T.dash}"`:''}/>`;
