$('igPng').onclick=()=>{const r=build(S);const img=new Image();$('igXMsg').textContent='Rendering…';img.onload=()=>{const c=document.createElement('canvas');c.width=r.W*2;c.height=r.H*2;const x=c.getContext('2d');x.scale(2,2);x.drawImage(img,0,0);c.toBlob(b=>{if(b)save(slug()+'.png',b);else $('igXMsg').textContent='Couldn\'t render the PNG.';},'image/png');};img.onerror=()=>{$('igXMsg').textContent='Couldn\'t render the PNG; try SVG.';};img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(r.svg);};

