const txt=el=>{if(!el)return '';const c=el.cloneNode(true);c.querySelectorAll('svg,button,select,input,textarea,.ptools,.ig-pbtn,script,style').forEach(x=>x.remove());return c.textContent.replace(/\s+/g,' ').trim();};
