 let secs=cards.map((c,i)=>{const h=clip(txt(c.querySelector(':scope>h3,:scope>h4')).replace(/^\p{Extended_Pictographic}️?\s*/u,''),50);const lis=[...c.querySelectorAll('li')].map(txt).filter(Boolean).slice(0,3).map(x=>clip(x,110));const body=lis.length?lis:sents(txt(c.querySelector('p'))||'',2,220).split(/(?<=[.!?…])\s+/).filter(Boolean).slice(0,2);return {h,b:body};}).filter(x=>x.h&&x.b.length);
 if(secs.length<3&&fl)secs=fl.def.nodes.filter(n=>n.t&&!n.pt).slice(0,8).map(n=>({h:clip(strip(n.t),50),b:[strip(n.s),...sents(strip(n.d),2,200).split(/(?<=[.!?…])\s+/)].filter(Boolean).slice(0,2)}));
 if(secs.length<3){const h2=[...sec.querySelectorAll(':scope>h2')];const more=h2.map(h=>{let n=h.nextElementSibling;while(n&&!/^(P|UL|DIV)$/.test(n.tagName))n=n.nextElementSibling;const t=n?txt(n):'';return {h:clip(txt(h),50),b:sents(t,2,220).split(/(?<=[.!?…])\s+/).filter(Boolean).slice(0,2)};}).filter(x=>x.b.length);secs=secs.concat(more).slice(0,8);}
 if(secs.length<3){const seen=new Set(secs.map(x=>x.h));[...sec.querySelectorAll('.card,.callout')].filter(c=>!c.closest('.ptools,.ig,.igm')&&c.offsetParent!==null).forEach(c=>{if(secs.length>=6)return;const hd=c.querySelector('h2,h3,h4,b,strong');const t=txt(c);if(t.length<40)return;let h=hd?clip(txt(hd),50):clip(t.split(/\s+/).slice(0,5).join(' '),50);if(seen.has(h))return;seen.add(h);const rest=hd?t.replace(txt(hd),'').trim():t;const b=sents(rest,2,200).split(/(?<=[.!?…])\s+/).filter(Boolean).slice(0,2);if(b.length)secs.push({h,b});});}
 if(!st.steps){const ls=(txt(sec.querySelector(':scope>p.lead'))||'').split(/(?<=[.!?])\s+/).map(x=>x.replace(/[.!?]$/,'')).sort((a,b)=>(b.match(/,/g)||[]).length-(a.match(/,/g)||[]).length)[0]||'';const parts=ls.split(/,\s*(?:and\s+|then\s+)?|\s+then\s+/).map(x=>x.trim()).filter(x=>x&&x.split(' ').length<=9);if(parts.length>=3)st.steps=parts.slice(0,6).map(x=>clip(x.charAt(0).toUpperCase()+x.slice(1),44)).join('\n');}
