 $('fdeForm').addEventListener('input',e=>{const k=e.target.dataset.k,c=e.target.dataset.c;D[cur]=D[cur]||{};if(k)D[cur][k]=e.target.value;if(c!=null){D[cur]['c'+c]=e.target.checked;render();}sv(K,D);});
 function mdOf(t){const d=D[t.k]||{};return `# ${t.n}\n\n_${t.d}_\n\n`+(t.c?t.c.map((c,i)=>`- [${d['c'+i]?'x':' '}] ${c}`).join('\n')+'\n\n':'')+t.f.map(([k,l])=>`## ${l}\n\n${(d[k]||'').trim()||'_TBD_'}`).join('\n\n');}
